entities/src/fulfillment/acceptance_elig:
//! `acceptance_eligibility`：客户验收资格与销售履约进度领域投影（数据模型
//! §6.7 / §4.3.1）。
//!
//! 三类履约事实（发货、电子交付、服务履约）的净验收数量（APPLY − REVERSE）、
//! 剩余可验收数量与销售履约进度派生集中在 `AcceptanceFactEligibility` /
//! `AcceptanceLineEligibility` / `AcceptanceProgress` 三个投影 VO；Service 只负责
//! 跨聚合加载、按销售行组织输入与最终视图映射。数量汇总一律受检：精度或溢出
//! 错误向上传递，禁止静默回退为零（FUL-E07）。

use rust_decimal::Decimal;

use erp_core::money::Quantity;
use erp_core::{Error, Result};
use erp_sales::entity::sales_order::FulfillmentProgress;

use super::acceptance_fulfillment_allocation::AcceptanceFulfillmentAllocation;

/// 单条履约事实的验收资格投影。
///
/// 由 Service 按事实行主键传入净成功履约数量与该事实的全部验收分配
/// （APPLY/REVERSE），本投影计算净验收数量与剩余可验收数量（守恒）。
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct AcceptanceFactEligibility {
    /// 履约事实行主键（发货行/电子交付/服务履约，跨域多态引用）。
    pub fulfillment_line_id: String,
    /// 净验收分配数量（APPLY − REVERSE）。
    pub net_accepted_quantity: Quantity,
    /// 剩余可验收数量（净成功履约数量 − 净验收数量）。
    pub eligible_quantity: Quantity,
}

impl AcceptanceFactEligibility {
    /// 计算单条履约事实的验收资格投影。
    ///
    /// 净验收与剩余可验收规则委托 [`AcceptanceFulfillmentAllocation`]，本类型
    /// 是三类履约事实共用的确定性投影入口。
    ///
    /// # 参数
    /// * `fulfillment_line_id` - 履约事实行主键
    /// * `net_successful_quantity` - 该事实的净成功履约数量
    /// * `allocations` - 该事实类型的全部验收分配（函数内按事实行主键过滤）
    ///
    /// # 返回
    /// 返回净验收与剩余可验收投影。
    ///
    /// # 错误
    /// 净验收为负、净验收超过净成功履约数量或数量超出统一精度时返回错误。
    pub fn from_fact(
        fulfillment_line_id: &str,
        net_successful_quantity: Quantity,
        allocations: &[AcceptanceFulfillmentAllocation],
    ) -> Result<Self> {
        let net_accepted_quantity =
            AcceptanceFulfillmentAllocation::net_quantity_for_fact(allocations, fulfillment_line_id)?;
        let eligible_quantity = AcceptanceFulfillmentAllocation::eligible_quantity_for_fact(
            net_successful_quantity,
            allocations,
            fulfillment_line_id,
        )?;
        Ok(Self {
            fulfillment_line_id: fulfillment_line_id.to_string(),
            net_accepted_quantity,
            eligible_quantity,
        })
    }
}

/// 销售行验收资格投影（一个销售稳定明细的全部履约事实汇总）。
///
/// 行级净验收与剩余可验收数量由逐事实投影受检汇总；任一事实的净验收超过
/// 成功履约数量或汇总溢出都会向上传递错误，禁止静默降为零（FUL-E07）。
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct AcceptanceLineEligibility {
    /// 销售稳定明细。
    pub sales_order_line_id: String,
    /// 应履约数量。
    pub required_quantity: Quantity,
    /// 逐事实资格投影（保持输入顺序）。
    pub facts: Vec<AcceptanceFactEligibility>,
    /// 净已验收数量（逐事实净验收的受检汇总）。
    pub net_accepted_quantity: Quantity,
    /// 剩余可验收数量（逐事实剩余的受检汇总）。
    pub remaining_eligible_quantity: Quantity,
}

impl AcceptanceLineEligibility {
    /// 汇总一个销售行的验收资格。
    ///
    /// # 参数
    /// * `sales_order_line_id` - 销售稳定明细
    /// * `required_quantity` - 销售行应履约数量
    /// * `facts` - 该销售行的逐事实资格投影（保持输入顺序）
    ///
    /// # 返回
    /// 返回行级净验收与剩余可验收汇总。
    ///
    /// # 错误
    /// 汇总算术溢出或结果超出统一数量精度时返回错误。
    pub fn from_facts(
        sales_order_line_id: String,
        required_quantity: Quantity,
        facts: Vec<AcceptanceFactEligibility>,
    ) -> Result<Self> {
        let mut net_accepted = Decimal::ZERO;
        let mut remaining_eligible = Decimal::ZERO;
        for fact in &facts {
            net_accepted = net_accepted
                .checked_add(fact.net_accepted_quantity.to_decimal())
                .ok_or_else(|| Error::from("净验收数量汇总溢出"))?;
            remaining_eligible = remaining_eligible
                .checked_add(fact.eligible_quantity.to_decimal())
                .ok_or_else(|| Error::from("剩余可验收数量汇总溢出"))?;
        }
        let net_accepted_quantity = Quantity::try_from(net_accepted)
            .map_err(|error| Error::from(format!("净验收数量超出统一精度：{error}")))?;
        let remaining_eligible_quantity = Quantity::try_from(remaining_eligible)
            .map_err(|error| Error::from(format!("剩余可验收数量超出统一精度：{error}")))?;
        Ok(Self {
            sales_order_line_id,
            required_quantity,
            facts,
            net_accepted_quantity,
            remaining_eligible_quantity,
        })
    }

    /// 判断销售行是否已全部验收。
    ///
    /// # 返回
    /// 净已验收数量不小于应履约数量时返回 `true`（应履约数量为零的行视为
    /// 已满足，与历史进度规则一致）。
    pub fn is_fully_fulfilled(&self) -> bool {
        self.net_accepted_quantity.to_decimal() >= self.required_quantity.to_decimal()
    }

    /// 判断销售行是否存在任一验收。
    ///
    /// # 返回
    /// 净已验收数量不为零时返回 `true`。
    pub fn has_acceptance(&self) -> bool {
        self.net_accepted_quantity.to_decimal() != Decimal::ZERO
    }

    /// 判断销售行是否仍存在剩余可验收数量。
    ///
    /// 每条事实的剩余可验收数量由投影保证非负，因此行级汇总不为零当且仅当
    /// 存在某条事实剩余可验收数量不为零。
    ///
    /// # 返回
    /// 行级剩余可验收数量不为零时返回 `true`。
    pub fn has_remaining_eligible(&self) -> bool {
        self.remaining_eligible_quantity.to_decimal() != Decimal::ZERO
    }
}

/// 销售单验收进度派生投影（数据模型 §4.3.1：客户验收通过即履约完成）。
///
/// 全部销售行净验收达到应履约数量 → 已完成；任一销售行存在验收但未全部
/// 完成 → 部分履约；否则 → 未开始。
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct AcceptanceProgress {
    /// 派生出的销售履约进度。
    pub progress: FulfillmentProgress,
    /// 是否仍存在剩余可验收数量。
    pub has_remaining_eligible: bool,
}

impl AcceptanceProgress {
    /// 从销售行资格投影派生销售单履约进度。
    ///
    /// # 参数
    /// * `lines` - 全部销售行的资格投影
    ///
    /// # 返回
    /// 存在销售行时返回进度与剩余可验收标记；没有任何销售行时返回 `None`，
    /// 表示无法派生进度（调用方不得写回进度）。
    pub fn derive(lines: &[AcceptanceLineEligibility]) -> Option<Self> {
        if lines.is_empty() {
            return None;
        }
        let mut all_fulfilled = true;
        let mut any_accepted = false;
        let mut has_remaining_eligible = false;
        for line in lines {
            all_fulfilled &= line.is_fully_fulfilled();
            any_accepted |= line.has_acceptance();
            has_remaining_eligible |= line.has_remaining_eligible();
        }
        let progress = if all_fulfilled {
            FulfillmentProgress::Completed
        } else if any_accepted {
            FulfillmentProgress::PartiallyFulfilled
        } else {
            FulfillmentProgress::NotStarted
        };
        Some(Self {
            progress,
            has_remaining_eligible,
        })
    }
}

#[cfg(test)]
mod tests {
    use std::str::FromStr;

    use rust_decimal::Decimal;

    use super::*;
    use crate::fulfillment::{
        AcceptanceFulfillmentAllocation, AcceptanceFulfillmentAllocationData, AllocationAction,
        FulfillmentFactType,
    };
    use erp_core::ids::AcceptanceFulfillmentAllocationId;

    /// 构造一条 APPLY 分配（默认数量 4）。
    fn apply_allocation(line_id: &str, quantity: &str) -> AcceptanceFulfillmentAllocation {
        AcceptanceFulfillmentAllocation::new(
            AcceptanceFulfillmentAllocationId::new(format!("allocation-{line_id}-{quantity}")),
            AcceptanceFulfillmentAllocationData {
                customer_acceptance_line_id: erp_core::ids::CustomerAcceptanceLineId::new(
                    "acceptance-line-1",
                ),
                fulfillment_fact_type: FulfillmentFactType::Delivery,
                fulfillment_line_id: line_id.to_string(),
                allocation_action: AllocationAction::Apply,
                allocated_quantity: Quantity::from_str(quantity).unwrap(),
                reverses_allocation_id: None,
            },
        )
        .unwrap()
    }

    /// 构造冲销 `applied` 的 REVERSE 分配。
    fn reverse_allocation(
        line_id: &str,
        quantity: &str,
        applied: &AcceptanceFulfillmentAllocation,
    ) -> AcceptanceFulfillmentAllocation {
        AcceptanceFulfillmentAllocation::new(
            AcceptanceFulfillmentAllocationId::new(format!("allocation-{line_id}-reverse")),
            AcceptanceFulfillmentAllocationData {
                customer_acceptance_line_id: erp_core::ids::CustomerAcceptanceLineId::new(
                    "acceptance-line-1",
                ),
                fulfillment_fact_type: FulfillmentFactType::Delivery,
                fulfillment_line_id: line_id.to_string(),
                allocation_action: AllocationAction::Reverse,
                allocated_quantity: Quantity::from_str(quantity).unwrap(),
                reverses_allocation_id: Some(applied.base.id.clone().into()),
            },
        )
        .unwrap()
    }

    /// 单条事实投影按 APPLY − REVERSE 计算净验收与剩余可验收数量。
    #[test]
    fn fact_projection_conserves_apply_reverse_net() {
        let applied = apply_allocation("dl-1", "4");
        let reversed = reverse_allocation("dl-1", "1.5", &applied);
        let allocations = vec![applied, reversed];
        let projection =
            AcceptanceFactEligibility::from_fact("dl-1", Quantity::from_str("5").unwrap(), &allocations)
                .unwrap();
        assert_eq!(projection.fulfillment_line_id, "dl-1");
        assert_eq!(
            projection.net_accepted_quantity,
            Quantity::from_str("2.5").unwrap()
        );
        assert_eq!(projection.eligible_quantity, Quantity::from_str("2.5").unwrap());
    }

    /// 净验收为负、净验收超过成功履约数量时投影明确失败，不得回退为零。
    #[test]
    fn fact_projection_fails_on_negative_net_or_over_acceptance() {
        let applied = apply_allocation("dl-1", "4");
        let reversed = reverse_allocation("dl-1", "4.5", &applied);
        assert!(AcceptanceFactEligibility::from_fact(
            "dl-1",
            Quantity::from_str("5").unwrap(),
            &[applied.clone(), reversed],
        )
        .is_err());

        let over = apply_allocation("dl-1", "6");
        assert!(AcceptanceFactEligibility::from_fact(
            "dl-1",
            Quantity::from_str("5").unwrap(),
            &[applied, over],
        )
        .is_err());
    }

    /// 行级投影按输入顺序汇总多条事实并保持事实顺序。
    #[test]
    fn line_projection_sums_facts_in_input_order() {
        let fact_a = AcceptanceFactEligibility {
            fulfillment_line_id: "dl-1".to_string(),
            net_accepted_quantity: Quantity::from_str("2.5").unwrap(),
            eligible_quantity: Quantity::from_str("2.5").unwrap(),
        };
        let fact_b = AcceptanceFactEligibility {
            fulfillment_line_id: "ed-1".to_string(),
            net_accepted_quantity: Quantity::from_str("1").unwrap(),
            eligible_quantity: Quantity::from_str("3").unwrap(),
        };
        let line = AcceptanceLineEligibility::from_facts(
            "sol-1".to_string(),
            Quantity::from_str("10").unwrap(),
            vec![fact_a.clone(), fact_b.clone()],
        )
        .unwrap();
        assert_eq!(line.net_accepted_quantity, Quantity::from_str("3.5").unwrap());
        assert_eq!(
            line.remaining_eligible_quantity,
            Quantity::from_str("5.5").unwrap()
        );
        assert_eq!(line.facts, vec![fact_a, fact_b]);
    }

    /// 空事实集合并入零应履约数量时行级汇总为零。
    #[test]
    fn line_projection_empty_facts_zeroes() {
        let line = AcceptanceLineEligibility::from_facts(
            "sol-1".to_string(),
            Quantity::from_str("0").unwrap(),
            Vec::new(),
        )
        .unwrap();
        assert_eq!(line.net_accepted_quantity, Quantity::from_str("0").unwrap());
        assert_eq!(line.remaining_eligible_quantity, Quantity::from_str("0").unwrap());
        assert!(line.is_fully_fulfilled());
        assert!(!line.has_acceptance());
        assert!(!line.has_remaining_eligible());
    }

    /// 汇总算术溢出时行级投影明确失败，不得回退为零。
    #[test]
    fn line_projection_overflow_fails() {
        let max = Quantity::from_str(&Decimal::MAX.to_string()).unwrap();
        let fact_a = AcceptanceFactEligibility {
            fulfillment_line_id: "dl-1".to_string(),
            net_accepted_quantity: max,
            eligible_quantity: Quantity::from_str("0").unwrap(),
        };
        let fact_b = AcceptanceFactEligibility {
            fulfillment_line_id: "dl-2".to_string(),
            net_accepted_quantity: max,
            eligible_quantity: Quantity::from_str("0").unwrap(),
        };
        let error = AcceptanceLineEligibility::from_facts(
            "sol-1".to_string(),
            Quantity::from_str("0").unwrap(),
            vec![fact_a, fact_b],
        )
        .unwrap_err();
        assert!(error.to_string().contains("溢出"));
    }

    /// 行级谓词覆盖未验收、部分验收与全部验收。
    #[test]
    fn line_predicates_cover_not_started_partial_full() {
        let no_acceptance = line_with_net(
            Quantity::from_str("0").unwrap(),
            Quantity::from_str("10").unwrap(),
        );
        assert!(!no_acceptance.has_acceptance());
        assert!(!no_acceptance.is_fully_fulfilled());

        let partial = line_with_net(
            Quantity::from_str("5").unwrap(),
            Quantity::from_str("10").unwrap(),
        );
        assert!(partial.has_acceptance());
        assert!(!partial.is_fully_fulfilled());

        let full = line_with_net(
            Quantity::from_str("10").unwrap(),
            Quantity::from_str("10").unwrap(),
        );
        assert!(full.has_acceptance());
        assert!(full.is_fully_fulfilled());

        let over = line_with_net(
            Quantity::from_str("12").unwrap(),
            Quantity::from_str("10").unwrap(),
        );
        assert!(over.is_fully_fulfilled());
    }

    /// 行级剩余可验收标记只在仍有剩余时成立。
    #[test]
    fn line_remaining_eligible_flag() {
        let remaining = line_with_net(
            Quantity::from_str("2").unwrap(),
            Quantity::from_str("10").unwrap(),
        );
        assert!(remaining.has_remaining_eligible());

        let exhausted = line_with_net(
            Quantity::from_str("10").unwrap(),
            Quantity::from_str("10").unwrap(),
        );
        assert!(!exhausted.has_remaining_eligible());
    }

    /// 进度派生覆盖未开始、部分履约、已完成及剩余可验收标记。
    #[test]
    fn progress_derive_covers_full_matrix() {
        let not_started = line_with_net(
            Quantity::from_str("0").unwrap(),
            Quantity::from_str("10").unwrap(),
        );
        let partial = line_with_net(
            Quantity::from_str("5").unwrap(),
            Quantity::from_str("10").unwrap(),
        );
        let full = line_with_net(
            Quantity::from_str("10").unwrap(),
            Quantity::from_str("10").unwrap(),
        );

        let derived = AcceptanceProgress::derive(std::slice::from_ref(&not_started)).unwrap();
        assert_eq!(derived.progress, FulfillmentProgress::NotStarted);
        assert!(derived.has_remaining_eligible);

        let derived = AcceptanceProgress::derive(std::slice::from_ref(&partial)).unwrap();
        assert_eq!(derived.progress, FulfillmentProgress::PartiallyFulfilled);
        assert!(derived.has_remaining_eligible);

        let derived = AcceptanceProgress::derive(std::slice::from_ref(&full)).unwrap();
        assert_eq!(derived.progress, FulfillmentProgress::Completed);
        assert!(!derived.has_remaining_eligible);

        // 一条未完成 + 一条完成 → 部分履约。
        let derived = AcceptanceProgress::derive(&[full, partial]).unwrap();
        assert_eq!(derived.progress, FulfillmentProgress::PartiallyFulfilled);

        // 全部行验收通过 → 已完成；剩余可验收标记跨行汇总。
        let derived = AcceptanceProgress::derive(&[
            line_with_net(
                Quantity::from_str("10").unwrap(),
                Quantity::from_str("10").unwrap(),
            ),
            line_with_net(Quantity::from_str("2").unwrap(), Quantity::from_str("2").unwrap()),
        ])
        .unwrap();
        assert_eq!(derived.progress, FulfillmentProgress::Completed);
        assert!(!derived.has_remaining_eligible);
    }

    /// 没有任何销售行时进度无法派生（调用方不得写回）。
    #[test]
    fn progress_derive_returns_none_for_empty_lines() {
        assert!(AcceptanceProgress::derive(&[]).is_none());
    }

    /// 构造指定净验收与应履约数量的行级投影。
    fn line_with_net(net_accepted: Quantity, required: Quantity) -> AcceptanceLineEligibility {
        AcceptanceLineEligibility::from_facts(
            "sol-1".to_string(),
            required,
            vec![AcceptanceFactEligibility {
                fulfillment_line_id: "dl-1".to_string(),
                net_accepted_quantity: net_accepted,
                eligible_quantity: Quantity::try_from(required.to_decimal() - net_accepted.to_decimal())
                    .unwrap(),
            }],
        )
        .unwrap()
    }
}

entities/src/fulfillment/acceptance_fulf:
//! `acceptance_fulfillment_allocation`：验收行对履约事实的分配（数据模型 §6.7）。
//!
//! 合同 §4.3 将所属 `CustomerAcceptance` 签署为 `NO_APPROVAL`：分配只表达履约
//! 事实覆盖，不得新增审批绑定字段、审批实例引用或任务归属。
//!
//! 同一验收行可以对应多批履约，同一履约事实可以分批验收；分配是正式事实，
//! 纠错通过追加 `REVERSE` 分配表达（§6.7）。Service 在验收事务内加载事实与
//! 全部分配；净数量、剩余可验收量和追加上限由本实体执行确定性校验（§8.2
//! 第 5 条）。

use entity_core::BaseModel;
use entity_macros::Entity;
use serde::{Deserialize, Serialize};

use erp_core::ids::{AcceptanceFulfillmentAllocationId, CustomerAcceptanceLineId};
use erp_core::money::Quantity;
use erp_core::{Error, Result};

/// 履约事实类型（数据模型 §6.7：发货、电子交付或服务履约事实）。
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "SCREAMING_SNAKE_CASE")]
pub enum FulfillmentFactType {
    /// 发货事实（`delivery_line`）。
    Delivery,
    /// 电子交付事实。
    ElectronicDelivery,
    /// 线下服务履约事实。
    ServiceFulfillment,
}

impl FulfillmentFactType {
    /// 返回类型的中文展示名。
    ///
    /// # 返回
    /// 返回面向用户的中文标签。
    pub fn label(&self) -> &'static str {
        match self {
            Self::Delivery => "发货",
            Self::ElectronicDelivery => "电子交付",
            Self::ServiceFulfillment => "服务履约",
        }
    }

    /// 返回类型的稳定代码。
    ///
    /// # 返回
    /// 返回用于持久化与查询的稳定字符串。
    pub fn as_str(&self) -> &'static str {
        match self {
            Self::Delivery => "DELIVERY",
            Self::ElectronicDelivery => "ELECTRONIC_DELIVERY",
            Self::ServiceFulfillment => "SERVICE_FULFILLMENT",
        }
    }
}

/// 分配动作（数据模型 §6.7：`APPLY` 或 `REVERSE`）。
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "SCREAMING_SNAKE_CASE")]
pub enum AllocationAction {
    /// 应用：把履约数量验收给验收行。
    Apply,
    /// 反向：冲销原分配。
    Reverse,
}

impl AllocationAction {
    /// 返回动作的中文展示名。
    ///
    /// # 返回
    /// 返回面向用户的中文标签。
    pub fn label(&self) -> &'static str {
        match self {
            Self::Apply => "应用",
            Self::Reverse => "反向",
        }
    }

    /// 返回动作的稳定代码。
    ///
    /// # 返回
    /// 返回用于持久化与查询的稳定字符串。
    pub fn as_str(&self) -> &'static str {
        match self {
            Self::Apply => "APPLY",
            Self::Reverse => "REVERSE",
        }
    }
}

/// 验收履约分配创建数据。
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
pub struct AcceptanceFulfillmentAllocationData {
    /// 验收结果行。
    pub customer_acceptance_line_id: CustomerAcceptanceLineId,
    /// 发货、电子交付或服务履约事实类型。
    pub fulfillment_fact_type: FulfillmentFactType,
    /// 履约事实行（发货行/电子交付/服务履约的主键，跨域多态引用）。
    pub fulfillment_line_id: String,
    /// 分配动作。
    pub allocation_action: AllocationAction,
    /// 正数验收数量。
    pub allocated_quantity: Quantity,
    /// 反向分配引用的原分配；`APPLY` 必须为空、`REVERSE` 必填。
    pub reverses_allocation_id: Option<AcceptanceFulfillmentAllocationId>,
}

/// 验收履约分配实体（数据模型 §6.7）。
///
/// 分配是正式事实，不设业务软删除（§4.5.1）；Service 加载同一履约事实的
/// 全部分配后，由本实体计算净验收数量并校验不超过净成功履约数量。
#[derive(Debug, Serialize, Deserialize, Clone, Entity, PartialEq, Eq)]
pub struct AcceptanceFulfillmentAllocation {
    #[serde(flatten)]
    pub base: BaseModel,
    /// 验收结果行。
    pub customer_acceptance_line_id: CustomerAcceptanceLineId,
    /// 履约事实类型。
    pub fulfillment_fact_type: FulfillmentFactType,
    /// 履约事实行（发货行/电子交付/服务履约主键）。
    pub fulfillment_line_id: String,
    /// 分配动作。
    pub allocation_action: AllocationAction,
    /// 正数验收数量。
    pub allocated_quantity: Quantity,
    /// 反向分配引用的原分配。
    pub reverses_allocation_id: Option<AcceptanceFulfillmentAllocationId>,
}

impl AcceptanceFulfillmentAllocation {
    /// 创建验收履约分配。
    ///
    /// 完成分配数量正数校验与动作-引用一致性校验：`APPLY` 不得携带反向引用，
    /// `REVERSE` 必须携带被冲销的原分配（§6.7）。`fulfillment_line_id` 按
    /// `fulfillment_fact_type` 对应发货行/电子交付/服务履约主键；因三类事实
    /// 没有统一 ID newtype，此处以字符串承载（地基修订候选：公共的
    /// `FulfillmentLineRef` 值对象），P3 按类型解析并校验存在性。
    ///
    /// # 参数
    /// * `id` - 实体主键（`erp_core::ids::AcceptanceFulfillmentAllocationId`）
    /// * `data` - 创建数据
    ///
    /// # 返回
    /// 返回新建的分配实体。
    ///
    /// # 错误
    /// 分配数量非正、履约事实引用为空，或动作与反向引用不一致时返回错误。
    pub fn new(
        id: AcceptanceFulfillmentAllocationId,
        data: AcceptanceFulfillmentAllocationData,
    ) -> Result<Self> {
        if data.allocated_quantity.to_decimal() <= rust_decimal::Decimal::ZERO {
            return Err(Error::from("分配数量必须为正数"));
        }
        let fulfillment_line_id = data.fulfillment_line_id.trim().to_string();
        if fulfillment_line_id.is_empty() {
            return Err(Error::from("履约事实引用不能为空"));
        }
        if data.allocation_action == AllocationAction::Reverse && data.reverses_allocation_id.is_none() {
            return Err(Error::from("反向分配必须引用原分配"));
        }
        if data.allocation_action == AllocationAction::Apply && data.reverses_allocation_id.is_some() {
            return Err(Error::from("应用分配不得携带反向引用"));
        }
        Ok(Self {
            base: BaseModel::new(id.to_string()),
            customer_acceptance_line_id: data.customer_acceptance_line_id,
            fulfillment_fact_type: data.fulfillment_fact_type,
            fulfillment_line_id,
            allocation_action: data.allocation_action,
            allocated_quantity: data.allocated_quantity,
            reverses_allocation_id: data.reverses_allocation_id,
        })
    }

    /// 计算指定履约事实的净验收分配数量。
    ///
    /// # 参数
    /// * `allocations` - 已加载的验收分配集合
    /// * `fulfillment_line_id` - 履约事实行主键
    ///
    /// # 返回
    /// 返回 `APPLY - REVERSE` 的净数量。
    ///
    /// # 错误
    /// 反向分配导致净数量为负，或结果超出统一数量精度范围时返回错误。
    pub fn net_quantity_for_fact(
        allocations: &[AcceptanceFulfillmentAllocation],
        fulfillment_line_id: &str,
    ) -> Result<Quantity> {
        let net = allocations
            .iter()
            .filter(|allocation| allocation.fulfillment_line_id == fulfillment_line_id)
            .fold(rust_decimal::Decimal::ZERO, |net, allocation| {
                match allocation.allocation_action {
                    AllocationAction::Apply => net + allocation.allocated_quantity.to_decimal(),
                    AllocationAction::Reverse => net - allocation.allocated_quantity.to_decimal(),
                }
            });
        if net < rust_decimal::Decimal::ZERO {
            return Err(Error::from("履约事实的净验收数量不得为负"));
        }
        Quantity::try_from(net).map_err(|error| Error::from(error.to_string()))
    }

    /// 计算履约事实剩余可验收数量。
    ///
    /// # 参数
    /// * `successful_quantity` - 履约事实的净成功数量
    /// * `allocations` - 已加载的验收分配集合
    /// * `fulfillment_line_id` - 履约事实行主键
    ///
    /// # 返回
    /// 返回成功数量减净验收分配后的剩余数量。
    ///
    /// # 错误
    /// 既有净验收已超过成功数量，或结果超出统一数量精度时返回错误。
    pub fn eligible_quantity_for_fact(
        successful_quantity: Quantity,
        allocations: &[AcceptanceFulfillmentAllocation],
        fulfillment_line_id: &str,
    ) -> Result<Quantity> {
        let net = Self::net_quantity_for_fact(allocations, fulfillment_line_id)?;
        if net.to_decimal() > successful_quantity.to_decimal() {
            return Err(Error::from("履约事实的净验收数量超过其净成功履约数量"));
        }
        Quantity::try_from(successful_quantity.to_decimal() - net.to_decimal())
            .map_err(|error| Error::from(error.to_string()))
    }

    /// 校验追加应用分配不会超过履约事实的净成功数量。
    ///
    /// # 参数
    /// * `successful_quantity` - 履约事实的净成功数量
    /// * `existing` - 该履约事实的既有分配
    /// * `fulfillment_line_id` - 履约事实行主键
    /// * `applying_quantity` - 本次拟追加的应用数量
    ///
    /// # 返回
    /// 追加后仍不超上限时返回 `Ok(())`。
    ///
    /// # 错误
    /// 净数量计算失败或追加后超过成功数量时返回错误。
    pub fn ensure_apply_within_successful_quantity(
        successful_quantity: Quantity,
        existing: &[AcceptanceFulfillmentAllocation],
        fulfillment_line_id: &str,
        applying_quantity: Quantity,
    ) -> Result<()> {
        let net = Self::net_quantity_for_fact(existing, fulfillment_line_id)?;
        if net.to_decimal() + applying_quantity.to_decimal() > successful_quantity.to_decimal() {
            return Err(Error::from("履约事实的净验收数量超过其净成功履约数量"));
        }
        Ok(())
    }

    /// 校验一组分配属于可冲正的原始验收事实。
    ///
    /// 原始验收只能包含至少一条 `APPLY`；由冲正生成的验收包含 `REVERSE`，
    /// 不得再次作为冲正目标，否则会形成没有业务数量变化的反向记录。
    ///
    /// # 参数
    /// * `allocations` - 待冲正验收单的全部履约分配
    ///
    /// # 返回
    /// 全部为原始应用分配时返回 `Ok(())`。
    ///
    /// # 错误
    /// 分配为空、包含反向动作或带有反向引用时返回错误。
    pub fn ensure_reversible_source(allocations: &[AcceptanceFulfillmentAllocation]) -> Result<()> {
        if allocations.is_empty() {
            return Err(Error::from("原验收单没有可冲正的分配，无法冲正"));
        }
        if allocations.iter().any(|allocation| {
            allocation.allocation_action != AllocationAction::Apply
                || allocation.reverses_allocation_id.is_some()
        }) {
            return Err(Error::from("冲正记录不能再次冲正"));
        }
        Ok(())
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use erp_core::ids::AcceptanceFulfillmentAllocationId;
    use std::str::FromStr;

    fn apply_data() -> AcceptanceFulfillmentAllocationData {
        AcceptanceFulfillmentAllocationData {
            customer_acceptance_line_id: CustomerAcceptanceLineId::new("acceptance-line-1"),
            fulfillment_fact_type: FulfillmentFactType::Delivery,
            fulfillment_line_id: " dl-1 ".to_string(),
            allocation_action: AllocationAction::Apply,
            allocated_quantity: Quantity::from_str("2").unwrap(),
            reverses_allocation_id: None,
        }
    }

    /// happy path：应用分配创建成功并规范化引用。
    #[test]
    fn new_apply_succeeds() {
        let allocation = AcceptanceFulfillmentAllocation::new(
            AcceptanceFulfillmentAllocationId::new("allocation-1"),
            apply_data(),
        )
        .unwrap();
        assert_eq!(allocation.fulfillment_line_id, "dl-1");
        assert_eq!(allocation.allocated_quantity, Quantity::from_str("2").unwrap());
        assert_eq!(allocation.allocation_action, AllocationAction::Apply);
    }

    /// happy path：反向分配创建成功。
    #[test]
    fn new_reverse_succeeds() {
        let data = AcceptanceFulfillmentAllocationData {
            allocation_action: AllocationAction::Reverse,
            reverses_allocation_id: Some(AcceptanceFulfillmentAllocationId::new("allocation-1")),
            ..apply_data()
        };
        let allocation = AcceptanceFulfillmentAllocation::new(
            AcceptanceFulfillmentAllocationId::new("allocation-2"),
            data,
        )
        .unwrap();
        assert_eq!(allocation.allocation_action, AllocationAction::Reverse);
    }

    /// 原始应用分配可冲正；空分配和反向分配均必须拒绝。
    #[test]
    fn reversible_source_rejects_empty_and_reverse_allocations() {
        let apply = AcceptanceFulfillmentAllocation::new(
            AcceptanceFulfillmentAllocationId::new("allocation-1"),
            apply_data(),
        )
        .unwrap();
        assert!(
            AcceptanceFulfillmentAllocation::ensure_reversible_source(std::slice::from_ref(&apply)).is_ok()
        );
        assert!(AcceptanceFulfillmentAllocation::ensure_reversible_source(&[]).is_err());

        let reverse = AcceptanceFulfillmentAllocation::new(
            AcceptanceFulfillmentAllocationId::new("allocation-2"),
            AcceptanceFulfillmentAllocationData {
                allocation_action: AllocationAction::Reverse,
                reverses_allocation_id: Some(AcceptanceFulfillmentAllocationId::new("allocation-1")),
                ..apply_data()
            },
        )
        .unwrap();
        let error = AcceptanceFulfillmentAllocation::ensure_reversible_source(&[reverse]).unwrap_err();
        assert!(error.to_string().contains("不能再次冲正"));
    }

    /// 失败路径：数量越界、引用为空、动作与反向引用不一致。
    #[test]
    fn new_rejects_invalid_inputs() {
        let zero_quantity = AcceptanceFulfillmentAllocationData {
            allocated_quantity: Quantity::from_str("0").unwrap(),
            ..apply_data()
        };
        assert!(AcceptanceFulfillmentAllocation::new(
            AcceptanceFulfillmentAllocationId::new("a1"),
            zero_quantity
        )
        .is_err());

        let blank_line = AcceptanceFulfillmentAllocationData {
            fulfillment_line_id: "   ".to_string(),
            ..apply_data()
        };
        assert!(AcceptanceFulfillmentAllocation::new(
            AcceptanceFulfillmentAllocationId::new("a2"),
            blank_line
        )
        .is_err());

        let reverse_without_reference = AcceptanceFulfillmentAllocationData {
            allocation_action: AllocationAction::Reverse,
            reverses_allocation_id: None,
            ..apply_data()
        };
        assert!(AcceptanceFulfillmentAllocation::new(
            AcceptanceFulfillmentAllocationId::new("a3"),
            reverse_without_reference
        )
        .is_err());

        let apply_with_reference = AcceptanceFulfillmentAllocationData {
            reverses_allocation_id: Some(AcceptanceFulfillmentAllocationId::new("allocation-9")),
            ..apply_data()
        };
        assert!(AcceptanceFulfillmentAllocation::new(
            AcceptanceFulfillmentAllocationId::new("a4"),
            apply_with_reference
        )
        .is_err());
    }

    /// 净分配与剩余可验收数量按 APPLY - REVERSE 计算。
    #[test]
    fn net_and_eligible_quantities_are_conserved() {
        let apply = AcceptanceFulfillmentAllocation::new(
            AcceptanceFulfillmentAllocationId::new("allocation-apply"),
            AcceptanceFulfillmentAllocationData {
                allocated_quantity: Quantity::from_str("4").unwrap(),
                ..apply_data()
            },
        )
        .unwrap();
        let reverse = AcceptanceFulfillmentAllocation::new(
            AcceptanceFulfillmentAllocationId::new("allocation-reverse"),
            AcceptanceFulfillmentAllocationData {
                allocation_action: AllocationAction::Reverse,
                allocated_quantity: Quantity::from_str("1.5").unwrap(),
                reverses_allocation_id: Some(AcceptanceFulfillmentAllocationId::new("allocation-apply")),
                ..apply_data()
            },
        )
        .unwrap();
        let allocations = vec![apply, reverse];
        assert_eq!(
            AcceptanceFulfillmentAllocation::net_quantity_for_fact(&allocations, "dl-1").unwrap(),
            Quantity::from_str("2.5").unwrap()
        );
        assert_eq!(
            AcceptanceFulfillmentAllocation::eligible_quantity_for_fact(
                Quantity::from_str("5").unwrap(),
                &allocations,
                "dl-1",
            )
            .unwrap(),
            Quantity::from_str("2.5").unwrap()
        );
        assert!(
            AcceptanceFulfillmentAllocation::ensure_apply_within_successful_quantity(
                Quantity::from_str("5").unwrap(),
                &allocations,
                "dl-1",
                Quantity::from_str("2.5").unwrap(),
            )
            .is_ok()
        );
        assert!(
            AcceptanceFulfillmentAllocation::ensure_apply_within_successful_quantity(
                Quantity::from_str("5").unwrap(),
                &allocations,
                "dl-1",
                Quantity::from_str("2.6").unwrap(),
            )
            .is_err()
        );
        assert!(AcceptanceFulfillmentAllocation::eligible_quantity_for_fact(
            Quantity::from_str("2").unwrap(),
            &allocations,
            "dl-1",
        )
        .is_err());
        assert!(AcceptanceFulfillmentAllocation::net_quantity_for_fact(
            std::slice::from_ref(&allocations[1]),
            "dl-1",
        )
        .is_err());
    }

    /// 序列化：枚举稳定代码；实体 BSON 往返。
    #[test]
    fn serde_shapes_and_bson_roundtrip() {
        assert_eq!(
            serde_json::to_string(&FulfillmentFactType::ElectronicDelivery).unwrap(),
            "\"ELECTRONIC_DELIVERY\""
        );
        assert_eq!(
            serde_json::to_string(&AllocationAction::Reverse).unwrap(),
            "\"REVERSE\""
        );
        assert_eq!(FulfillmentFactType::ServiceFulfillment.label(), "服务履约");

        let allocation = AcceptanceFulfillmentAllocation::new(
            AcceptanceFulfillmentAllocationId::new("allocation-5"),
            apply_data(),
        )
        .unwrap();
        let roundtrip: AcceptanceFulfillmentAllocation =
            bson::deserialize_from_document(bson::serialize_to_document(&allocation).unwrap()).unwrap();
        assert_eq!(roundtrip, allocation);
    }

    /// 验收分配无审批约束：不得出现绑定字段、实例或任务归属。
    #[test]
    fn allocation_has_no_approval_binding_or_work_item() {
        let allocation = AcceptanceFulfillmentAllocation::new(
            AcceptanceFulfillmentAllocationId::new("allocation-1"),
            apply_data(),
        )
        .unwrap();
        let value = serde_json::to_value(&allocation).unwrap();
        let object = value.as_object().expect("分配序列化为对象");
        assert!(!object.contains_key("approval_binding"));
        assert!(!object.contains_key("approval_instance_id"));
        assert!(!object.contains_key("work_item_id"));
        assert!(!object.contains_key("approval_subject_version"));

        let production = include_str!("acceptance_fulfillment_allocation.rs")
            .split("#[cfg(test)]")
            .next()
            .expect("生产代码");
        assert!(!production.contains("IN_APPROVAL"));
        assert!(!production.contains("fn start_approval"));
        assert!(!production.contains("ApprovalDefinitionBinding"));
        assert!(!production.contains("WorkItem"));
        assert!(!production.contains("approval_instance"));
    }
}

entities/src/fulfillment/customer_accept:
//! `customer_acceptance` / `customer_acceptance_line`：客户验收单及行（数据模型 §6.7）。
//!
//! 合同 §4.3 签署为 `NO_APPROVAL`：实体只保留业务状态，不得新增审批绑定字段
//! 或审批状态机。
//!
//! 状态机按 §7.5：草稿 → 已过账 → 已冲正（`POSTED` 后不可编辑，误录时新增
//! 反向验收及反向分配，不覆盖原行）。非卡券明细只有累计净有效验收通过数量
//! 达到当前有效履约数量时才算履约完成；短少、拒收和服务不通过只记录结果，
//! 不直接改库存、应收或采购。Service 负责加载履约事实与分配，本实体负责草稿/
//! 过账/冲正资格、表头行归属及分配数量守恒。

use entity_core::BaseModel;
use entity_macros::Entity;
use serde::{Deserialize, Serialize};

use erp_core::common::state::{ensure_transition, DocumentState};
use erp_core::common::time::Instant;
use erp_core::ids::{
    CustomerAcceptanceId, CustomerAcceptanceLineId, FileAssetId, SalesOrderId, SalesOrderLineId,
};
use erp_core::money::Quantity;
use erp_core::validation::normalize_optional_text;
use erp_core::validation::normalize_required_text;
use erp_core::{Error, Result};

/// 验收单号最大长度。
const ACCEPTANCE_NO_MAX_LEN: usize = 64;
/// 依据说明最大长度。
const REASON_MAX_LEN: usize = 512;

/// 客户验收单状态（数据模型 §6.7：草稿、已过账、已冲正）。
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "SCREAMING_SNAKE_CASE")]
pub enum CustomerAcceptanceState {
    /// 草稿。
    Draft,
    /// 已过账（不可编辑，误录走反向验收）。
    Posted,
    /// 已冲正（不可逆终态）。
    Reversed,
}

impl CustomerAcceptanceState {
    /// 返回状态的中文展示名。
    ///
    /// # 返回
    /// 返回面向用户的中文标签。
    pub fn label(&self) -> &'static str {
        match self {
            Self::Draft => "草稿",
            Self::Posted => "已过账",
            Self::Reversed => "已冲正",
        }
    }

    /// 返回状态的稳定代码。
    ///
    /// # 返回
    /// 返回用于持久化与查询的稳定字符串。
    pub fn as_str(&self) -> &'static str {
        match self {
            Self::Draft => "DRAFT",
            Self::Posted => "POSTED",
            Self::Reversed => "REVERSED",
        }
    }

    /// 判断是否可编辑（仅草稿）。
    ///
    /// # 返回
    /// 草稿状态返回 `true`。
    pub fn is_editable(&self) -> bool {
        matches!(self, Self::Draft)
    }
}

impl DocumentState for CustomerAcceptanceState {
    /// 固定邻接矩阵（§7.5 定向链，`REVERSED` 为不可逆终态）。
    fn allowed_next(self) -> &'static [Self] {
        match self {
            Self::Draft => &[Self::Posted],
            Self::Posted => &[Self::Reversed],
            Self::Reversed => &[],
        }
    }
}

/// 验收结果（数据模型 §6.7：通过、短少、拒收、服务不通过）。
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "SCREAMING_SNAKE_CASE")]
pub enum AcceptanceResult {
    /// 通过。
    Passed,
    /// 短少。
    Shortage,
    /// 拒收。
    Rejected,
    /// 服务不通过。
    ServiceFailed,
}

impl AcceptanceResult {
    /// 返回结果的中文展示名。
    ///
    /// # 返回
    /// 返回面向用户的中文标签。
    pub fn label(&self) -> &'static str {
        match self {
            Self::Passed => "通过",
            Self::Shortage => "短少",
            Self::Rejected => "拒收",
            Self::ServiceFailed => "服务不通过",
        }
    }

    /// 返回结果的稳定代码。
    ///
    /// # 返回
    /// 返回用于持久化与查询的稳定字符串。
    pub fn as_str(&self) -> &'static str {
        match self {
            Self::Passed => "PASSED",
            Self::Shortage => "SHORTAGE",
            Self::Rejected => "REJECTED",
            Self::ServiceFailed => "SERVICE_FAILED",
        }
    }
}

/// 客户验收单创建数据。
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
pub struct CustomerAcceptanceData {
    /// 客户验收单号（全局唯一）。
    pub acceptance_no: String,
    /// 销售单。
    pub sales_order_id: SalesOrderId,
    /// 验收时间。
    pub accepted_at: Instant,
    /// 验收结果。
    pub result: AcceptanceResult,
}

/// 客户验收单更新数据（仅草稿可更新）。
#[derive(Debug, Clone, Default, Serialize, Deserialize, PartialEq, Eq)]
pub struct CustomerAcceptanceUpdate {
    /// 验收时间；`None` 表示不修改。
    pub accepted_at: Option<Instant>,
    /// 验收结果；`None` 表示不修改。
    pub result: Option<AcceptanceResult>,
}

/// 客户验收单实体（数据模型 §6.7 表头）。
///
/// `reversal_of_acceptance_id` 记录误录验收的反向事实（可空），由冲正动作写入；
/// 已过账/已冲正不设业务软删除（§4.5.1）。
#[derive(Debug, Serialize, Deserialize, Clone, Entity, PartialEq, Eq)]
pub struct CustomerAcceptance {
    #[serde(flatten)]
    pub base: BaseModel,
    /// 客户验收单号。
    pub acceptance_no: String,
    /// 销售单。
    pub sales_order_id: SalesOrderId,
    /// 验收时间。
    pub accepted_at: Instant,
    /// 验收结果。
    pub result: AcceptanceResult,
    /// 当前状态。
    pub status: CustomerAcceptanceState,
    /// 误录验收的反向事实。
    pub reversal_of_acceptance_id: Option<CustomerAcceptanceId>,
}

impl CustomerAcceptance {
    /// 创建客户验收单（初始状态为草稿）。
    ///
    /// 完成验收单号规范化。
    ///
    /// # 参数
    /// * `id` - 实体主键（`erp_core::ids::CustomerAcceptanceId`）
    /// * `data` - 创建数据
    ///
    /// # 返回
    /// 返回新建的验收单实体。
    ///
    /// # 错误
    /// 验收单号为空或超长时返回错误。
    pub fn new(id: CustomerAcceptanceId, data: CustomerAcceptanceData) -> Result<Self> {
        let acceptance_no = normalize_required_text(
            data.acceptance_no,
            "客户验收单号不能为空",
            ACCEPTANCE_NO_MAX_LEN,
            "客户验收单号过长",
        )?;
        Ok(Self {
            base: BaseModel::new(id.to_string()),
            acceptance_no,
            sales_order_id: data.sales_order_id,
            accepted_at: data.accepted_at,
            result: data.result,
            status: CustomerAcceptanceState::Draft,
            reversal_of_acceptance_id: None,
        })
    }

    /// 更新客户验收单（仅草稿）。
    ///
    /// 已过账验收不可编辑（§6.7），误录时新增反向验收及反向分配。
    ///
    /// # 参数
    /// * `update` - 更新数据
    ///
    /// # 返回
    /// 更新成功返回 `Ok(())`。
    ///
    /// # 错误
    /// 状态不可编辑时返回错误。
    pub fn update(&mut self, update: CustomerAcceptanceUpdate) -> Result<()> {
        self.ensure_editable()?;
        if let Some(accepted_at) = update.accepted_at {
            self.accepted_at = accepted_at;
        }
        if let Some(result) = update.result {
            self.result = result;
        }
        Ok(())
    }

    /// 判断既有验收单是否属于同一业务身份。
    ///
    /// # 参数
    /// * `sales_order_id` - 请求声明的销售单
    /// * `acceptance_no` - 请求可选的验收单号
    ///
    /// # 返回
    /// 销售单一致，且提供单号时单号也一致，返回 `true`。
    pub fn matches_business_identity(
        &self,
        sales_order_id: &SalesOrderId,
        acceptance_no: Option<&str>,
    ) -> bool {
        self.sales_order_id == *sales_order_id
            && acceptance_no.is_none_or(|acceptance_no| self.acceptance_no == acceptance_no)
    }

    /// 判断验收单是否已经过账。
    ///
    /// # 返回
    /// 状态为 `Posted` 时返回 `true`。
    pub fn is_posted(&self) -> bool {
        self.status == CustomerAcceptanceState::Posted
    }

    /// 校验已有验收草稿可按期望版本完整替换。
    ///
    /// # 参数
    /// * `expected_version` - 调用方提交的乐观锁版本
    ///
    /// # 返回
    /// 草稿且版本一致时返回 `Ok(())`。
    ///
    /// # 错误
    /// 状态或版本不满足时返回错误。
    pub fn ensure_draft_version(&self, expected_version: u64) -> Result<()> {
        if self.status != CustomerAcceptanceState::Draft {
            return Err(Error::from("只有草稿状态的客户验收单可以登记"));
        }
        if self.base.version != expected_version {
            return Err(Error::from("客户验收草稿已变化，请刷新后重试"));
        }
        Ok(())
    }

    /// 校验验收单仍为草稿。
    ///
    /// # 返回
    /// 草稿状态返回 `Ok(())`。
    ///
    /// # 错误
    /// 非草稿状态返回错误。
    pub fn ensure_draft(&self) -> Result<()> {
        if self.status != CustomerAcceptanceState::Draft {
            return Err(Error::from("只有草稿状态的客户验收单可以过账"));
        }
        Ok(())
    }

    /// 校验已加载验收行完整且全部归属本单。
    ///
    /// # 参数
    /// * `lines` - 已在事务内加载的验收行
    ///
    /// # 返回
    /// 至少一行且全部行归属本单时返回 `Ok(())`。
    ///
    /// # 错误
    /// 空行或行表头关联不一致时返回错误。
    pub fn ensure_posting_lines(&self, lines: &[CustomerAcceptanceLine]) -> Result<()> {
        if lines.is_empty() {
            return Err(Error::from("客户验收单没有行，无法过账"));
        }
        let acceptance_id = CustomerAcceptanceId::new(self.base.id.clone());
        if lines
            .iter()
            .any(|line| line.customer_acceptance_id != acceptance_id)
        {
            return Err(Error::from("客户验收行与验收单关联不一致"));
        }
        Ok(())
    }

    /// 校验验收单可按期望版本冲正。
    ///
    /// # 参数
    /// * `expected_version` - 调用方提交的乐观锁版本
    ///
    /// # 返回
    /// 已过账且版本一致时返回 `Ok(())`。
    ///
    /// # 错误
    /// 状态或版本不满足时返回错误。
    pub fn ensure_reversible(&self, expected_version: u64) -> Result<()> {
        if self.base.version != expected_version {
            return Err(Error::from("数据已被其他请求修改，请刷新后重试"));
        }
        if self.status != CustomerAcceptanceState::Posted {
            return Err(Error::from("只有已过账的客户验收单可以冲正"));
        }
        Ok(())
    }

    /// 过账验收（草稿 → 已过账）。
    ///
    /// 过账时写 `acceptance_fulfillment_allocation` 的 `APPLY`/`REVERSE` 并重算
    /// 两侧净数量上限——由 P3 在过账事务中完成（§8.2 第 5 条）。
    ///
    /// # 返回
    /// 迁移成功返回 `Ok(())`。
    ///
    /// # 错误
    /// 当前状态不允许迁移（非草稿）时返回错误。
    pub fn mark_posted(&mut self) -> Result<()> {
        ensure_transition(self.status, CustomerAcceptanceState::Posted)?;
        self.status = CustomerAcceptanceState::Posted;
        Ok(())
    }

    /// 冲正验收（已过账 → 已冲正，终态）。
    ///
    /// 误录时新增反向验收及反向分配，不覆盖原行（§6.7）；本方法登记反向
    /// 验收单引用并迁移状态，反向分配由 P3 形成。
    ///
    /// # 参数
    /// * `reversal_of_acceptance_id` - 反向验收单主键
    ///
    /// # 返回
    /// 迁移成功返回 `Ok(())`。
    ///
    /// # 错误
    /// 当前状态不允许迁移，或反向验收引用与自身相同/为空时返回错误。
    pub fn reverse(&mut self, reversal_of_acceptance_id: CustomerAcceptanceId) -> Result<()> {
        ensure_transition(self.status, CustomerAcceptanceState::Reversed)?;
        if reversal_of_acceptance_id == CustomerAcceptanceId::new(self.base.id.clone()) {
            return Err(Error::from("反向验收不能引用自身"));
        }
        self.reversal_of_acceptance_id = Some(reversal_of_acceptance_id);
        self.status = CustomerAcceptanceState::Reversed;
        Ok(())
    }

    /// 判断当前状态是否可编辑。
    ///
    /// # 返回
    /// 草稿状态返回 `true`。
    pub fn is_editable(&self) -> bool {
        self.status.is_editable()
    }

    /// 校验当前状态可编辑。
    ///
    /// # 返回
    /// 可编辑返回 `Ok(())`。
    ///
    /// # 错误
    /// 已过账/已冲正的验收单不可编辑时返回错误。
    fn ensure_editable(&self) -> Result<()> {
        if !self.is_editable() {
            return Err(Error::from("已过账或已冲正的客户验收单不可编辑"));
        }
        Ok(())
    }
}

/// 客户验收行创建数据。
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
pub struct CustomerAcceptanceLineData {
    /// 验收单。
    pub customer_acceptance_id: CustomerAcceptanceId,
    /// 稳定行号（单内从 1 递增）。
    pub line_no: u32,
    /// 验收明细。
    pub sales_order_line_id: SalesOrderLineId,
    /// 通过数量。
    pub accepted_quantity: Quantity,
    /// 短少数量。
    pub short_quantity: Quantity,
    /// 拒收数量。
    pub rejected_quantity: Quantity,
    /// 依据说明。
    pub reason: Option<String>,
    /// 业务凭证。
    pub evidence_attachment_id: Option<FileAssetId>,
}

/// 客户验收行实体（数据模型 §6.7 行）。
///
/// 三个结果数量均不得为负；短少、拒收和服务不通过只记录结果，不直接改库存、
/// 应收或采购。Service 加载分配后，由本实体校验分配合计等于通过数量，并校验
/// 履约事实销售明细与验收行一致。
#[derive(Debug, Serialize, Deserialize, Clone, Entity, PartialEq, Eq)]
pub struct CustomerAcceptanceLine {
    #[serde(flatten)]
    pub base: BaseModel,
    /// 验收单。
    pub customer_acceptance_id: CustomerAcceptanceId,
    /// 稳定行号。
    pub line_no: u32,
    /// 验收明细。
    pub sales_order_line_id: SalesOrderLineId,
    /// 通过数量。
    pub accepted_quantity: Quantity,
    /// 短少数量。
    pub short_quantity: Quantity,
    /// 拒收数量。
    pub rejected_quantity: Quantity,
    /// 依据说明。
    pub reason: Option<String>,
    /// 业务凭证。
    pub evidence_attachment_id: Option<FileAssetId>,
}

impl CustomerAcceptanceLine {
    /// 创建客户验收行。
    ///
    /// 完成行号、依据说明规范化与数量非负校验。行级约束
    /// `(customer_acceptance_id, line_no)` 唯一由唯一索引保证；验收单已过账后
    /// 行不可再变更由 P3 按表头状态把关（§6.7）。
    ///
    /// # 参数
    /// * `id` - 实体主键（`erp_core::ids::CustomerAcceptanceLineId`）
    /// * `data` - 创建数据
    ///
    /// # 返回
    /// 返回新建的验收行实体。
    ///
    /// # 错误
    /// 行号小于 1、结果数量为负或依据说明超长时返回错误。
    pub fn new(id: CustomerAcceptanceLineId, data: CustomerAcceptanceLineData) -> Result<Self> {
        let reason = normalize_optional_text(data.reason, "依据说明", REASON_MAX_LEN)?;
        if data.line_no < 1 {
            return Err(Error::from("行号必须从 1 开始"));
        }
        if data.accepted_quantity.to_decimal() < rust_decimal::Decimal::ZERO
            || data.short_quantity.to_decimal() < rust_decimal::Decimal::ZERO
            || data.rejected_quantity.to_decimal() < rust_decimal::Decimal::ZERO
        {
            return Err(Error::from("验收行结果数量不得为负"));
        }
        Ok(Self {
            base: BaseModel::new(id.to_string()),
            customer_acceptance_id: data.customer_acceptance_id,
            line_no: data.line_no,
            sales_order_line_id: data.sales_order_line_id,
            accepted_quantity: data.accepted_quantity,
            short_quantity: data.short_quantity,
            rejected_quantity: data.rejected_quantity,
            reason,
            evidence_attachment_id: data.evidence_attachment_id,
        })
    }

    /// 校验履约分配合计等于本行通过数量。
    ///
    /// # 参数
    /// * `allocated_quantities` - 本行全部拟应用分配数量
    ///
    /// # 返回
    /// 分配合计守恒时返回 `Ok(())`。
    ///
    /// # 错误
    /// 数量求和失败或合计不等于通过数量时返回错误。
    pub fn ensure_allocation_conserved<I>(&self, allocated_quantities: I) -> Result<()>
    where
        I: IntoIterator<Item = Quantity>,
    {
        let total =
            allocated_quantities
                .into_iter()
                .try_fold(rust_decimal::Decimal::ZERO, |total, quantity| {
                    Quantity::try_from(total + quantity.to_decimal())
                        .map(|quantity| quantity.to_decimal())
                        .map_err(|error| Error::from(error.to_string()))
                })?;
        if total != self.accepted_quantity.to_decimal() {
            return Err(Error::from("验收行分配合计必须等于通过数量"));
        }
        Ok(())
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use erp_core::ids::CustomerAcceptanceId;
    use std::str::FromStr;

    fn data() -> CustomerAcceptanceData {
        CustomerAcceptanceData {
            acceptance_no: " CA-2026-001 ".to_string(),
            sales_order_id: SalesOrderId::new("so-1"),
            accepted_at: Instant::from_unix_secs(1_700_000_000),
            result: AcceptanceResult::Passed,
        }
    }

    fn line_data() -> CustomerAcceptanceLineData {
        CustomerAcceptanceLineData {
            customer_acceptance_id: CustomerAcceptanceId::new("acceptance-1"),
            line_no: 1,
            sales_order_line_id: SalesOrderLineId::new("so-line-1"),
            accepted_quantity: Quantity::from_str("9").unwrap(),
            short_quantity: Quantity::from_str("1").unwrap(),
            rejected_quantity: Quantity::from_str("0").unwrap(),
            reason: Some(" 部分短少 ".to_string()),
            evidence_attachment_id: None,
        }
    }

    /// happy path：单号规范化、初始草稿、过账与冲正（登记反向验收）全链路。
    #[test]
    fn new_normalizes_no_and_drives_state_machine() {
        let mut acceptance =
            CustomerAcceptance::new(CustomerAcceptanceId::new("acceptance-1"), data()).unwrap();
        assert_eq!(acceptance.acceptance_no, "CA-2026-001");
        assert_eq!(acceptance.status, CustomerAcceptanceState::Draft);
        assert!(acceptance.reversal_of_acceptance_id.is_none());

        acceptance.mark_posted().unwrap();
        assert_eq!(acceptance.status, CustomerAcceptanceState::Posted);
        acceptance
            .reverse(CustomerAcceptanceId::new("acceptance-2"))
            .unwrap();
        assert_eq!(acceptance.status, CustomerAcceptanceState::Reversed);
        assert_eq!(
            acceptance.reversal_of_acceptance_id.unwrap().as_ref(),
            "acceptance-2"
        );
    }

    /// 失败路径：必填空（单号空白）、超长、反向验收引用自身。
    #[test]
    fn new_rejects_invalid_inputs() {
        let blank_no = CustomerAcceptanceData {
            acceptance_no: "  ".to_string(),
            ..data()
        };
        assert!(CustomerAcceptance::new(CustomerAcceptanceId::new("a2"), blank_no).is_err());

        let overlong_no = CustomerAcceptanceData {
            acceptance_no: "x".repeat(65),
            ..data()
        };
        assert!(CustomerAcceptance::new(CustomerAcceptanceId::new("a3"), overlong_no).is_err());

        let mut acceptance = CustomerAcceptance::new(CustomerAcceptanceId::new("a4"), data()).unwrap();
        assert!(
            acceptance.reverse(CustomerAcceptanceId::new("a4")).is_err(),
            "不能引用自身"
        );
        assert!(
            acceptance.reverse(CustomerAcceptanceId::new("other")).is_err(),
            "草稿不能冲正"
        );
    }

    /// 状态机：合法/非法/终态定向断言（含幂等迁移）。
    #[test]
    fn state_machine_directed_edges() {
        let mut acceptance = CustomerAcceptance::new(CustomerAcceptanceId::new("a5"), data()).unwrap();
        assert!(acceptance
            .update(CustomerAcceptanceUpdate {
                result: Some(AcceptanceResult::Shortage),
                ..Default::default()
            })
            .is_ok());
        assert_eq!(acceptance.result, AcceptanceResult::Shortage);
        acceptance.mark_posted().unwrap();
        // from == to 幂等迁移恒合法（state.rs 契约）；POSTED 不可编辑由 update 把关。
        assert!(acceptance.mark_posted().is_ok());
        assert!(
            acceptance.update(CustomerAcceptanceUpdate::default()).is_err(),
            "已过账不可编辑"
        );
        assert!(acceptance.reverse(CustomerAcceptanceId::new("a6")).is_ok());
        assert!(
            acceptance.reverse(CustomerAcceptanceId::new("a7")).is_ok(),
            "REVERSED 幂等迁移合法，且无法迁移到其他状态"
        );

        assert!(ensure_transition(CustomerAcceptanceState::Draft, CustomerAcceptanceState::Posted).is_ok());
        assert!(
            ensure_transition(CustomerAcceptanceState::Posted, CustomerAcceptanceState::Reversed).is_ok()
        );
        assert!(
            ensure_transition(CustomerAcceptanceState::Draft, CustomerAcceptanceState::Reversed).is_err()
        );
        assert!(
            ensure_transition(CustomerAcceptanceState::Reversed, CustomerAcceptanceState::Posted).is_err()
        );
        assert!(ensure_transition(CustomerAcceptanceState::Draft, CustomerAcceptanceState::Draft).is_ok());
    }

    /// happy path：验收行创建成功，说明规范化。
    #[test]
    fn line_new_succeeds() {
        let line = CustomerAcceptanceLine::new(CustomerAcceptanceLineId::new("cl-1"), line_data()).unwrap();
        assert_eq!(line.reason.as_deref(), Some("部分短少"));
        assert_eq!(line.accepted_quantity, Quantity::from_str("9").unwrap());
    }

    /// 过账规则校验业务身份、版本、表头行归属、分配守恒与冲正资格。
    #[test]
    fn posting_rules_validate_status_version_association_and_allocation_total() {
        let mut acceptance =
            CustomerAcceptance::new(CustomerAcceptanceId::new("acceptance-1"), data()).unwrap();
        let line =
            CustomerAcceptanceLine::new(CustomerAcceptanceLineId::new("line-posting"), line_data()).unwrap();
        assert!(acceptance.matches_business_identity(&SalesOrderId::new("so-1"), Some("CA-2026-001"),));
        assert!(!acceptance.matches_business_identity(&SalesOrderId::new("other-order"), None));
        assert!(!acceptance.matches_business_identity(&SalesOrderId::new("so-1"), Some("other-no")));
        assert!(acceptance.ensure_draft_version(acceptance.base.version).is_ok());
        assert!(acceptance
            .ensure_draft_version(acceptance.base.version + 1)
            .is_err());
        assert!(acceptance.ensure_draft().is_ok());
        assert!(acceptance.ensure_posting_lines(&[]).is_err());
        assert!(acceptance
            .ensure_posting_lines(std::slice::from_ref(&line))
            .is_ok());
        let foreign_line = CustomerAcceptanceLine::new(
            CustomerAcceptanceLineId::new("foreign-line"),
            CustomerAcceptanceLineData {
                customer_acceptance_id: CustomerAcceptanceId::new("other-acceptance"),
                ..line_data()
            },
        )
        .unwrap();
        assert!(acceptance
            .ensure_posting_lines(std::slice::from_ref(&foreign_line))
            .is_err());
        assert!(line
            .ensure_allocation_conserved([Quantity::from_str("9").unwrap()])
            .is_ok());
        assert!(line
            .ensure_allocation_conserved([Quantity::from_str("8").unwrap()])
            .is_err());
        acceptance.mark_posted().unwrap();
        assert!(acceptance.ensure_draft().is_err());
        assert!(acceptance.ensure_draft_version(acceptance.base.version).is_err());
        assert!(acceptance.ensure_reversible(acceptance.base.version + 1).is_err());
        assert!(acceptance.ensure_reversible(acceptance.base.version).is_ok());
    }

    #[test]
    fn line_rejects_quantity_violations() {
        let negative = CustomerAcceptanceLineData {
            short_quantity: Quantity::from_str("-1").unwrap(),
            ..line_data()
        };
        assert!(CustomerAcceptanceLine::new(CustomerAcceptanceLineId::new("cl-2"), negative).is_err());

        let zero_line_no = CustomerAcceptanceLineData {
            line_no: 0,
            ..line_data()
        };
        assert!(CustomerAcceptanceLine::new(CustomerAcceptanceLineId::new("cl-3"), zero_line_no).is_err());

        let overlong_reason = CustomerAcceptanceLineData {
            reason: Some("x".repeat(513)),
            ..line_data()
        };
        assert!(CustomerAcceptanceLine::new(CustomerAcceptanceLineId::new("cl-4"), overlong_reason).is_err());
    }

    /// 序列化：结果枚举稳定代码；实体 BSON 往返。
    #[test]
    fn serde_shapes_and_bson_roundtrip() {
        assert_eq!(
            serde_json::to_string(&AcceptanceResult::ServiceFailed).unwrap(),
            "\"SERVICE_FAILED\""
        );
        assert_eq!(
            serde_json::to_string(&CustomerAcceptanceState::Posted).unwrap(),
            "\"POSTED\""
        );
        assert_eq!(AcceptanceResult::Shortage.label(), "短少");

        let mut acceptance = CustomerAcceptance::new(CustomerAcceptanceId::new("a8"), data()).unwrap();
        acceptance.mark_posted().unwrap();
        let roundtrip: CustomerAcceptance =
            bson::deserialize_from_document(bson::serialize_to_document(&acceptance).unwrap()).unwrap();
        assert_eq!(roundtrip, acceptance);
    }

    /// 客户验收单无审批约束：不得出现绑定字段或审批状态机。
    #[test]
    fn customer_acceptance_has_no_approval_binding_or_state_machine() {
        let acceptance = CustomerAcceptance::new(CustomerAcceptanceId::new("acceptance-1"), data()).unwrap();
        let value = serde_json::to_value(&acceptance).unwrap();
        let object = value.as_object().expect("验收单序列化为对象");
        assert!(!object.contains_key("approval_binding"));
        assert!(!object.contains_key("approval_subject_version"));
        assert!(!object.contains_key("pending_allocations"));
        assert_eq!(acceptance.status, CustomerAcceptanceState::Draft);
        assert_eq!(CustomerAcceptanceState::Draft.as_str(), "DRAFT");
        assert_eq!(CustomerAcceptanceState::Posted.as_str(), "POSTED");
        assert_eq!(CustomerAcceptanceState::Reversed.as_str(), "REVERSED");

        let production = include_str!("customer_acceptance.rs")
            .split("#[cfg(test)]")
            .next()
            .expect("生产代码");
        assert!(!production.contains("IN_APPROVAL"));
        assert!(!production.contains("fn start_approval"));
        assert!(!production.contains("approval_subject_version"));
        assert!(!production.contains("ApprovalDefinitionBinding"));
        assert!(!production.contains("PENDING_REVIEW"));
    }
}

//! `CustomerAcceptanceLine` 批量工厂（FUL-E02）。
//!
//! 验收行输入顺序、连续行号、默认无凭证与数量约束的唯一规则源。

use serde::{Deserialize, Serialize};

use crate::fulfillment::{CustomerAcceptanceLine, CustomerAcceptanceLineData};
use erp_core::ids::{CustomerAcceptanceId, CustomerAcceptanceLineId, SalesOrderLineId};
use erp_core::money::Quantity;
use erp_core::{Error, Result};

/// 单行领域输入（已验证形态，不含行号/表头/凭证）。
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
pub struct CustomerAcceptanceLineSpec {
    /// 行主键（Service 注入系统 ID）。
    pub line_id: CustomerAcceptanceLineId,
    /// 验收明细。
    pub sales_order_line_id: SalesOrderLineId,
    /// 通过数量。
    pub accepted_quantity: Quantity,
    /// 短少数量。
    pub short_quantity: Quantity,
    /// 拒收数量。
    pub rejected_quantity: Quantity,
    /// 依据说明。
    pub reason: Option<String>,
}

/// 验收行批量构造上限（DTO 校验 `1-200` 的领域侧等价）。
pub const ACCEPTANCE_LINE_BATCH_MAX: usize = 200;

/// `CustomerAcceptanceLine` 批量构造入口。
pub struct CustomerAcceptanceLineBatch;

impl CustomerAcceptanceLineBatch {
    /// 按输入顺序从 1 连续编号批量构造验收行。
    ///
    /// # 参数
    /// * `acceptance_id` - 所属验收单主键
    /// * `specs` - 与输入顺序一致的行规格（含 Service 注入的行 ID）
    ///
    /// # 返回
    /// 返回与输入顺序一致的行实体集合（凭证统一为 `None`）。
    ///
    /// # 错误
    /// 空输入、超过 200 行或行级数量/说明违规时返回错误。
    ///
    /// # 约束
    /// 无 I/O、无时钟、无 ID 生成；空行在此失败，调用方不得先建表头。
    pub fn build(
        acceptance_id: CustomerAcceptanceId,
        specs: Vec<CustomerAcceptanceLineSpec>,
    ) -> Result<Vec<CustomerAcceptanceLine>> {
        if specs.is_empty() {
            return Err(Error::from("客户验收单至少需要一行"));
        }
        if specs.len() > ACCEPTANCE_LINE_BATCH_MAX {
            return Err(Error::from("验收行数必须在1-200之间"));
        }
        let mut lines = Vec::with_capacity(specs.len());
        for (index, spec) in specs.into_iter().enumerate() {
            let line_no = u32::try_from(index + 1).map_err(|_| Error::from("验收行号溢出"))?;
            lines.push(CustomerAcceptanceLine::new(
                spec.line_id,
                CustomerAcceptanceLineData {
                    customer_acceptance_id: acceptance_id.clone(),
                    line_no,
                    sales_order_line_id: spec.sales_order_line_id,
                    accepted_quantity: spec.accepted_quantity,
                    short_quantity: spec.short_quantity,
                    rejected_quantity: spec.rejected_quantity,
                    reason: spec.reason,
                    evidence_attachment_id: None,
                },
            )?);
        }
        Ok(lines)
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::str::FromStr;

    fn spec(id: &str) -> CustomerAcceptanceLineSpec {
        CustomerAcceptanceLineSpec {
            line_id: CustomerAcceptanceLineId::new(id),
            sales_order_line_id: SalesOrderLineId::new("so-line-1"),
            accepted_quantity: Quantity::from_str("9").unwrap(),
            short_quantity: Quantity::from_str("1").unwrap(),
            rejected_quantity: Quantity::from_str("0").unwrap(),
            reason: Some("短少".to_string()),
        }
    }

    /// 正常路径：输入顺序与行号一一对应，凭证默认为空。
    #[test]
    fn build_preserves_order_and_defaults_no_evidence() {
        let lines = CustomerAcceptanceLineBatch::build(
            CustomerAcceptanceId::new("a-1"),
            vec![spec("l-1"), spec("l-2")],
        )
        .unwrap();
        assert_eq!(lines[0].line_no, 1);
        assert_eq!(lines[1].line_no, 2);
        assert!(lines[0].evidence_attachment_id.is_none());
    }

    /// 数量约束由实体直接覆盖：负数量失败。
    #[test]
    fn quantity_violations_fail() {
        assert!(CustomerAcceptanceLineBatch::build(
            CustomerAcceptanceId::new("a-1"),
            vec![CustomerAcceptanceLineSpec {
                accepted_quantity: Quantity::from_str("-1").unwrap(),
                ..spec("l-1")
            }],
        )
        .is_err());
    }

    /// 原因超长失败。
    #[test]
    fn overlong_reason_fails() {
        assert!(CustomerAcceptanceLineBatch::build(
            CustomerAcceptanceId::new("a-1"),
            vec![CustomerAcceptanceLineSpec {
                reason: Some("x".repeat(513)),
                ..spec("l-1")
            }],
        )
        .is_err());
    }

    /// 空行失败（调用方不得先建表头）；超 200 行失败。
    #[test]
    fn empty_and_oversized_batches_fail() {
        assert!(CustomerAcceptanceLineBatch::build(CustomerAcceptanceId::new("a-1"), vec![]).is_err());
        let many = (0..201).map(|i| spec(&format!("l-{i}"))).collect::<Vec<_>>();
        assert!(CustomerAcceptanceLineBatch::build(CustomerAcceptanceId::new("a-1"), many).is_err());
    }
}

