            },
        )
        .unwrap()
    }

    /// happy path：单号规范化、初始草稿、过账与冲正全链路。
    #[test]
    fn new_normalizes_no_and_drives_state_machine() {
        let mut receipt = PurchaseReceipt::new(PurchaseReceiptId::new("receipt-1"), receipt_data()).unwrap();
        assert_eq!(receipt.receipt_no, "PR-2026-001");
        assert_eq!(receipt.status, PurchaseReceiptState::Draft);
        assert!(receipt.is_editable());

        receipt
            .mark_posted(Instant::from_unix_secs(1_700_000_000), " operator-1 ")
            .unwrap();
        assert_eq!(receipt.status, PurchaseReceiptState::Posted);
        assert_eq!(receipt.posted_by.as_deref(), Some("operator-1"));
        assert_eq!(receipt.posted_at.unwrap().unix_secs(), 1_700_000_000);

        receipt.reverse().unwrap();
        assert_eq!(receipt.status, PurchaseReceiptState::Reversed);
    }

    /// 失败路径：必填空（单号空白）与超长。
    #[test]
    fn new_rejects_blank_or_overlong_no() {
        let blank = PurchaseReceiptData {
            receipt_no: "   ".to_string(),
            ..receipt_data()
        };
        assert!(PurchaseReceipt::new(PurchaseReceiptId::new("r2"), blank).is_err());

        let overlong = PurchaseReceiptData {
            receipt_no: "x".repeat(65),
            ..receipt_data()
        };
        assert!(PurchaseReceipt::new(PurchaseReceiptId::new("r3"), overlong).is_err());
    }

    /// 状态机：合法/非法/终态定向断言（含不可逆终态 REVERSED，逐边定向）。
    #[test]
    fn state_machine_directed_edges() {
        let mut receipt = PurchaseReceipt::new(PurchaseReceiptId::new("receipt-2"), receipt_data()).unwrap();
        assert!(receipt.reverse().is_err(), "草稿不能直接冲正");
        assert!(receipt
            .update(PurchaseReceiptUpdate {
                warehouse_id: Some(WarehouseId::new("wh-2")),
            })
            .is_ok());
        receipt
            .mark_posted(Instant::from_unix_secs(1_700_000_000), "operator-1")
            .unwrap();
        assert!(
            receipt
                .update(PurchaseReceiptUpdate { warehouse_id: None })
                .is_err(),
            "已过账不可编辑"
        );
        // from == to 幂等迁移恒合法（state.rs 契约）；POSTED 不可编辑由 update 把关。
        assert!(receipt
            .mark_posted(Instant::from_unix_secs(1_700_000_100), "o2")
            .is_ok());
        assert!(receipt.reverse().is_ok());
        assert!(
            receipt.reverse().is_ok(),
            "REVERSED 幂等迁移合法，且无法迁移到其他状态"
        );
    }

    /// 状态机：固定邻接矩阵的合法/非法迁移（幂等合法）。
    #[test]
    fn state_machine_transition_matrix() {
        assert!(ensure_transition(PurchaseReceiptState::Draft, PurchaseReceiptState::Draft).is_ok());
        assert!(ensure_transition(PurchaseReceiptState::Draft, PurchaseReceiptState::Posted).is_ok());
        assert!(ensure_transition(PurchaseReceiptState::Posted, PurchaseReceiptState::Reversed).is_ok());
        assert!(ensure_transition(PurchaseReceiptState::Draft, PurchaseReceiptState::Reversed).is_err());
        assert!(ensure_transition(PurchaseReceiptState::Posted, PurchaseReceiptState::Draft).is_err());
        assert!(ensure_transition(PurchaseReceiptState::Reversed, PurchaseReceiptState::Posted).is_err());
        assert!(ensure_transition(PurchaseReceiptState::Reversed, PurchaseReceiptState::Reversed).is_ok());
    }

    /// happy path：行创建成功，字段完整。
    #[test]
    fn line_new_succeeds() {
        let line = PurchaseReceiptLine::new(PurchaseReceiptLineId::new("line-1"), line_data()).unwrap();
        assert_eq!(line.line_no, 1);
        assert_eq!(line.qualified_quantity, Quantity::from_str("9").unwrap());
        assert_eq!(line.rejected_quantity, Quantity::from_str("1").unwrap());
        assert_eq!(line.quality_result, QualityResult::Partial);
    }

    #[test]
    fn quality_result_is_derived_deterministically_and_mismatch_is_rejected() {
        assert_eq!(
            QualityResult::from_quantities(
                Quantity::from_str("10").unwrap(),
                Quantity::from_str("0").unwrap(),
            ),
            QualityResult::Passed
        );
        assert_eq!(
            QualityResult::from_quantities(
                Quantity::from_str("0").unwrap(),
                Quantity::from_str("10").unwrap(),
            ),
            QualityResult::Rejected
        );
        assert_eq!(
            QualityResult::from_quantities(
                Quantity::from_str("9").unwrap(),
                Quantity::from_str("1").unwrap(),
            ),
            QualityResult::Partial
        );

        let inconsistent = PurchaseReceiptLineData {
            quality_result: QualityResult::Passed,
            ..line_data()
        };
        assert!(PurchaseReceiptLine::new(PurchaseReceiptLineId::new("line-invalid"), inconsistent).is_err());
    }

    /// 失败路径：数量越界（合计超过到货）与负数量。
    #[test]
    fn line_rejects_quantity_violations() {
        let over_sum = PurchaseReceiptLineData {
            qualified_quantity: Quantity::from_str("9.5").unwrap(),
            ..line_data()
        };
        assert!(PurchaseReceiptLine::new(PurchaseReceiptLineId::new("l2"), over_sum).is_err());

        let negative = PurchaseReceiptLineData {
            rejected_quantity: Quantity::from_str("-0.5").unwrap(),
            ..line_data()
        };
        assert!(PurchaseReceiptLine::new(PurchaseReceiptLineId::new("l3"), negative).is_err());

        let zero_line_no = PurchaseReceiptLineData {
            line_no: 0,
            ..line_data()
        };
        assert!(PurchaseReceiptLine::new(PurchaseReceiptLineId::new("l4"), zero_line_no).is_err());
    }

    /// 过账资格校验状态、版本、表头行归属、超收和预占分摊守恒。
    #[test]
    fn posting_rules_are_entity_owned() {
        let mut receipt = PurchaseReceipt::new(PurchaseReceiptId::new("receipt-1"), receipt_data()).unwrap();
        let line = PurchaseReceiptLine::new(PurchaseReceiptLineId::new("line-rule"), line_data()).unwrap();
        assert!(receipt.ensure_draft_version(receipt.base.version).is_ok());
        assert!(receipt.ensure_draft_version(receipt.base.version + 1).is_err());
        assert!(receipt.ensure_posting_lines(&[]).is_err());
        assert!(receipt.ensure_posting_lines(std::slice::from_ref(&line)).is_ok());
        let foreign_line = PurchaseReceiptLine::new(
            PurchaseReceiptLineId::new("foreign-line"),
            PurchaseReceiptLineData {
                purchase_receipt_id: PurchaseReceiptId::new("other-receipt"),
                ..line_data()
            },
        )
        .unwrap();
        assert!(receipt
            .ensure_posting_lines(std::slice::from_ref(&foreign_line))
            .is_err());

        let revision_line = revision_line(Quantity::from_str("10").unwrap());
        assert!(line
            .ensure_within_revision(&revision_line, Quantity::from_str("0").unwrap(),)
            .is_ok());
        assert!(line
            .ensure_within_revision(&revision_line, Quantity::from_str("1").unwrap(),)
            .is_err());
        let mut foreign_revision_line = revision_line.clone();
        foreign_revision_line.base.id = "other-po-line".to_string();
        assert!(line
            .ensure_within_revision(&foreign_revision_line, Quantity::from_str("0").unwrap())
            .is_err());

        let shares = line
            .reservation_shares(
                &[
                    Quantity::from_str("3").unwrap(),
                    Quantity::from_str("2").unwrap(),
                    Quantity::from_str("5").unwrap(),
                ],
                Quantity::from_str("10").unwrap(),
            )
            .unwrap();
        assert_eq!(shares[0], Quantity::from_str("2.7").unwrap());
        assert_eq!(shares[1], Quantity::from_str("1.8").unwrap());
        assert_eq!(shares[2], Quantity::from_str("4.5").unwrap());
        assert!(line
            .reservation_shares(
                &[Quantity::from_str("1").unwrap()],
                Quantity::from_str("0").unwrap()
            )
            .is_err());

        let mut received = HashMap::new();
        received.insert(
            PurchaseOrderRevisionLineId::new("po-line-1"),
            Quantity::from_str("10").unwrap(),
        );
        assert_eq!(
            PurchaseReceipt::fulfillment_progress(std::slice::from_ref(&revision_line), &received),
            ProgressStatus::Completed,
        );
        assert_eq!(
            PurchaseReceipt::fulfillment_progress(std::slice::from_ref(&revision_line), &HashMap::new()),
            ProgressStatus::Partial,
        );
        receipt
            .mark_posted(Instant::from_unix_secs(1_700_000_000), "operator-1")
            .unwrap();
        assert!(receipt.ensure_draft_version(receipt.base.version).is_err());
    }

    /// 采购来源履约资格校验采购状态、先款门槛与分配两端关联。
    #[test]
    fn purchase_fulfillment_eligibility_checks_loaded_context() {
        assert!(
            PurchaseFulfillmentEligibility::ensure_order_fulfillable(PurchaseOrderStatus::Effective,).is_ok()
        );
        assert!(
            PurchaseFulfillmentEligibility::ensure_order_fulfillable(PurchaseOrderStatus::Draft,).is_err()
        );

        let snapshot = PaymentTermSnapshot::new(
            "PREPAY_50".to_string(),
            true,
            Some(Amount::from_str("50.00").unwrap()),
            Some(erp_core::money::Rate::from_str("0.500000").unwrap()),
            resolve_procurement_payment_term,
        )
        .unwrap();
        assert!(PurchaseFulfillmentEligibility::ensure_prepayment_satisfied(
            &snapshot,
            Amount::from_str("100.00").unwrap(),
            Amount::from_str("50.00").unwrap(),
        )
        .is_ok());
        assert!(PurchaseFulfillmentEligibility::ensure_prepayment_satisfied(
            &snapshot,
            Amount::from_str("100.00").unwrap(),
            Amount::from_str("49.99").unwrap(),
        )
        .is_err());
        let ratio_only = PaymentTermSnapshot::new(
            "PREPAY_100".to_string(),
            true,
            None,
            Some(erp_core::money::Rate::from_str("0.750000").unwrap()),
            resolve_procurement_payment_term,
        )
        .unwrap();
        assert!(PurchaseFulfillmentEligibility::ensure_prepayment_satisfied(
            &ratio_only,
            Amount::from_str("100.00").unwrap(),
            Amount::from_str("74.99").unwrap(),
        )
        .is_err());
        let gate_disabled = PaymentTermSnapshot::new(
            "NET-30".to_string(),
            false,
            Some(Amount::from_str("100.00").unwrap()),
            None,
            resolve_procurement_payment_term,
        )
        .unwrap();
        assert!(PurchaseFulfillmentEligibility::ensure_prepayment_satisfied(
            &gate_disabled,
            Amount::from_str("100.00").unwrap(),
            Amount::from_str("0.00").unwrap(),
        )
        .is_ok());

        let allocation = PurchaseLineSalesAllocation::new(
            erp_core::ids::PurchaseLineSalesAllocationId::new("allocation-1"),
            erp_procurement::entity::purchase_order::PurchaseLineSalesAllocationData {
                purchase_order_revision_line_id: PurchaseOrderRevisionLineId::new("po-line-1"),
                sales_order_revision_line_id: SalesOrderRevisionLineId::new("sales-revision-line-1"),
                allocated_quantity: Quantity::from_str("10").unwrap(),
                allocated_cost_gross: Amount::from_str("100.00").unwrap(),
                allocated_cost_net: Amount::from_str("87.00").unwrap(),
            },
        )
        .unwrap();
        let purchase_line_ids = [PurchaseOrderRevisionLineId::new("po-line-1")];
        let sales_revision_line_id = SalesOrderRevisionLineId::new("sales-revision-line-1");
        let sales_order_line_id = SalesOrderLineId::new("sales-line-1");
        assert!(PurchaseFulfillmentEligibility::ensure_allocation_consistent(
            &allocation,
            &purchase_line_ids,
            Some((&sales_revision_line_id, &sales_order_line_id)),
            &sales_order_line_id,
        )
        .is_ok());
        assert!(PurchaseFulfillmentEligibility::ensure_allocation_consistent(
            &allocation,
            &[],
            Some((&sales_revision_line_id, &sales_order_line_id)),
            &sales_order_line_id,
        )
        .is_err());
        let other_sales_order_line_id = SalesOrderLineId::new("other-sales-line");
        assert!(PurchaseFulfillmentEligibility::ensure_allocation_consistent(
            &allocation,
            &purchase_line_ids,
            Some((&sales_revision_line_id, &other_sales_order_line_id)),
            &sales_order_line_id,
        )
        .is_err());
        assert!(PurchaseFulfillmentEligibility::ensure_allocation_consistent(
            &allocation,
            &purchase_line_ids,
            None,
            &sales_order_line_id,
        )
        .is_err());
    }

    /// 序列化：状态/质量结果枚举输出稳定代码；实体 BSON 往返。
    #[test]
    fn serde_shapes_and_bson_roundtrip() {
        assert_eq!(
            serde_json::to_string(&PurchaseReceiptState::Posted).unwrap(),
            "\"POSTED\""
        );
        assert_eq!(
            serde_json::to_string(&QualityResult::Partial).unwrap(),
            "\"PARTIAL\""
        );
        assert_eq!(PurchaseReceiptState::Reversed.label(), "已冲正");

        let mut receipt = PurchaseReceipt::new(PurchaseReceiptId::new("receipt-3"), receipt_data()).unwrap();
        receipt
            .mark_posted(Instant::from_unix_secs(1_700_000_000), "operator-1")
            .unwrap();
        let roundtrip: PurchaseReceipt =
            bson::deserialize_from_document(bson::serialize_to_document(&receipt).unwrap()).unwrap();
        assert_eq!(roundtrip, receipt);
    }

    /// 采购收货单无审批约束：不得出现绑定字段或审批状态机。
    #[test]
    fn purchase_receipt_has_no_approval_binding_or_state_machine() {
        let receipt = PurchaseReceipt::new(PurchaseReceiptId::new("receipt-1"), receipt_data()).unwrap();
        let value = serde_json::to_value(&receipt).unwrap();
        let object = value.as_object().expect("入库单序列化为对象");
        assert!(!object.contains_key("approval_binding"));
        assert!(!object.contains_key("approval_subject_version"));
        assert!(!object.contains_key("pending_allocations"));
        assert_eq!(receipt.status, PurchaseReceiptState::Draft);
        assert_eq!(PurchaseReceiptState::Draft.as_str(), "DRAFT");
        assert_eq!(PurchaseReceiptState::Posted.as_str(), "POSTED");
        assert_eq!(PurchaseReceiptState::Reversed.as_str(), "REVERSED");

        let production = include_str!("purchase_receipt.rs")
            .split("#[cfg(test)]")
            .next()
            .expect("生产代码");
        assert!(!production.contains("IN_APPROVAL"));
        assert!(!production.contains("fn start_approval"));
        assert!(!production.contains("approval_subject_version"));
        assert!(!production.contains("ApprovalDefinitionBinding"));
        assert!(!production.contains("PENDING_REVIEW"));
    }
}

//! `PurchaseReceiptLine` 批量工厂（FUL-E03）。
//!
//! 入库行连续编号与请求到领域数据转换的唯一规则源；质量规则不复制。

use serde::{Deserialize, Serialize};

use crate::fulfillment::{PurchaseReceiptLine, PurchaseReceiptLineData, QualityResult};
use erp_core::ids::{PurchaseOrderRevisionLineId, PurchaseReceiptId, PurchaseReceiptLineId};
use erp_core::money::Quantity;
use erp_core::{Error, Result};

/// 单行领域输入（不含行号/质量结果派生）。
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
pub struct PurchaseReceiptLineSpec {
    /// 行主键（Service 注入系统 ID）。
    pub line_id: PurchaseReceiptLineId,
    /// 采购明细。
    pub purchase_order_revision_line_id: PurchaseOrderRevisionLineId,
    /// 到货数量。
    pub received_quantity: Quantity,
    /// 合格数量。
    pub qualified_quantity: Quantity,
    /// 不合格数量。
    pub rejected_quantity: Quantity,
}

/// `PurchaseReceiptLine` 批量构造入口。
pub struct PurchaseReceiptLineBatch;

impl PurchaseReceiptLineBatch {
    /// 按输入顺序从 1 连续编号批量构造入库行。
    ///
    /// # 参数
    /// * `receipt_id` - 所属入库单主键
    /// * `specs` - 与输入顺序一致的行规格（含 Service 注入的行 ID）
    ///
    /// # 返回
    /// 返回与输入顺序一致的行实体集合。
    ///
    /// # 错误
    /// 空输入、行号溢出或数量/守恒违规时返回错误。
    ///
    /// # 约束
    /// 质量结果一律经 `QualityResult::from_quantities` 派生，不得接受调用方传入值。
    pub fn build(
        receipt_id: PurchaseReceiptId,
        specs: Vec<PurchaseReceiptLineSpec>,
    ) -> Result<Vec<PurchaseReceiptLine>> {
        if specs.is_empty() {
            return Err(Error::from("采购入库单至少需要一行"));
        }
        let mut lines = Vec::with_capacity(specs.len());
        for (index, spec) in specs.into_iter().enumerate() {
            let line_no = u32::try_from(index + 1).map_err(|_| Error::from("入库行号溢出"))?;
            let quality_result =
                QualityResult::from_quantities(spec.qualified_quantity, spec.rejected_quantity);
            lines.push(PurchaseReceiptLine::new(
                spec.line_id,
                PurchaseReceiptLineData {
                    purchase_receipt_id: receipt_id.clone(),
                    line_no,
                    purchase_order_revision_line_id: spec.purchase_order_revision_line_id,
                    received_quantity: spec.received_quantity,
                    qualified_quantity: spec.qualified_quantity,
                    rejected_quantity: spec.rejected_quantity,
                    quality_result,
                },
            )?);
        }
        Ok(lines)
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::str::FromStr;

    fn spec(id: &str) -> PurchaseReceiptLineSpec {
        PurchaseReceiptLineSpec {
            line_id: PurchaseReceiptLineId::new(id),
            purchase_order_revision_line_id: PurchaseOrderRevisionLineId::new("po-line-1"),
            received_quantity: Quantity::from_str("10").unwrap(),
            qualified_quantity: Quantity::from_str("9").unwrap(),
            rejected_quantity: Quantity::from_str("1").unwrap(),
        }
    }

    /// 正常路径：输入顺序与行号一一对应，质量按数量派生。
    #[test]
    fn build_preserves_order_and_derives_quality() {
        let lines =
            PurchaseReceiptLineBatch::build(PurchaseReceiptId::new("r-1"), vec![spec("l-1")]).unwrap();
        assert_eq!(lines[0].line_no, 1);
        assert_eq!(lines[0].quality_result, QualityResult::Partial);
    }

    /// 全合格与全拒收均由实体规则派生。
    #[test]
    fn full_pass_and_full_reject_derive() {
        let pass = PurchaseReceiptLineBatch::build(
            PurchaseReceiptId::new("r-1"),
            vec![PurchaseReceiptLineSpec {
                qualified_quantity: Quantity::from_str("10").unwrap(),
                rejected_quantity: Quantity::from_str("0").unwrap(),
                ..spec("l-1")
            }],
        )
        .unwrap();
        assert_eq!(pass[0].quality_result, QualityResult::Passed);
        let reject = PurchaseReceiptLineBatch::build(
            PurchaseReceiptId::new("r-1"),
            vec![PurchaseReceiptLineSpec {
                qualified_quantity: Quantity::from_str("0").unwrap(),
                rejected_quantity: Quantity::from_str("10").unwrap(),
                ..spec("l-2")
            }],
        )
        .unwrap();
        assert_eq!(reject[0].quality_result, QualityResult::Rejected);
    }

    /// 数量守恒违规失败；空输入失败。
    #[test]
    fn quantity_conservation_and_empty_fail() {
        assert!(PurchaseReceiptLineBatch::build(
            PurchaseReceiptId::new("r-1"),
            vec![PurchaseReceiptLineSpec {
                received_quantity: Quantity::from_str("5").unwrap(),
                ..spec("l-1")
            }],
        )
        .is_err());
        assert!(PurchaseReceiptLineBatch::build(PurchaseReceiptId::new("r-1"), vec![]).is_err());
    }
}

entities/src/fulfillment/service_evidenc:
//! `service_evidence`：线下服务履约确认的证据值对象（实际服务地点与现场图片
//! 凭证元数据策略）。
//!
//! 数据模型 §6.7 要求确认命令把采购审核占位草稿替换为实际服务地点，并登记
//! 敏感、长期保留的现场图片凭证。本模块持有两套无 I/O 的纯规则：
//! - [`ActualServiceLocation`]：地点 trim 与占位值/空白拒绝，只向 Service
//!   输出已规范化明文；加密与查询指纹仍由 Service 完成（§4.5.5，密钥不得
//!   进入实体层）；
//! - [`ServiceEvidencePolicy`]：现场图片凭证的 MIME 白名单、敏感级别、保留
//!   策略与销毁状态校验，待登记与既有资产两条确认路径必须使用同一策略。
//!
//! 错误信息为固定文案，不携带地点明文或文件敏感元数据。

use erp_core::{Error, Result};
use erp_support::{RetentionClass, SensitivityClass};

/// 采购审核草稿使用的服务地点占位值；确认时必须替换为实际地点。
pub const SERVICE_LOCATION_PLACEHOLDER: &str = "待填写";

/// 已规范化并校验通过的实际服务地点。
///
/// 只承载去除首尾空白、非空且不是采购审核占位值的明文；地点加密值与查询
/// 指纹由 Service 使用 [`crate::fulfillment::ServiceFulfillment`] 的指纹函数
/// 与加密编解码器计算，本值对象不接触密钥或密文。
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ActualServiceLocation(String);

impl ActualServiceLocation {
    /// 解析并规范化实际服务地点。
    ///
    /// # 参数
    /// * `raw` - 确认命令中的原始服务地点
    ///
    /// # 返回
    /// 返回去除首尾空白且非占位值的实际地点。
    ///
    /// # 错误
    /// 空白或仍为「待填写」占位值时返回 `LogicError`；错误文案不包含输入
    /// 明文，避免地点敏感值进入日志。
    pub fn parse(raw: &str) -> Result<Self> {
        let service_location = raw.trim();
        if service_location.is_empty() {
            return Err(Error::from("服务地点不能为空"));
        }
        if service_location == SERVICE_LOCATION_PLACEHOLDER {
            return Err(Error::from("请填写实际服务地点"));
        }
        Ok(Self(service_location.to_string()))
    }

    /// 返回规范化后的地点明文引用。
    ///
    /// # 返回
    /// 返回去除首尾空白的服务地点字符串引用。
    pub fn as_str(&self) -> &str {
        &self.0
    }
}

/// 现场图片凭证元数据策略（数据模型 §6.7）。
///
/// 固定允许 `image/jpeg`、`image/png`、`image/webp`，且必须按敏感文件保存、
/// 长期保留、未被销毁。待登记（multipart 本批次）与既有资产（已持久化
/// `file_asset`）两条确认路径必须调用同一策略，禁止在 Service 复制规则。
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub struct ServiceEvidencePolicy;

impl ServiceEvidencePolicy {
    /// 校验现场图片凭证元数据。
    ///
    /// # 参数
    /// * `content_type` - 文件 MIME 类型
    /// * `sensitivity` - 敏感级别
    /// * `retention` - 保留策略
    /// * `destroyed` - 是否已销毁
    ///
    /// # 返回
    /// 元数据合法时返回 `Ok(())`。
    ///
    /// # 错误
    /// 非图片、非敏感、非长期保留或已销毁时返回 `LogicError`；错误文案为
    /// 固定提示，不包含文件敏感元数据。
    pub fn validate(
        content_type: &str,
        sensitivity: SensitivityClass,
        retention: RetentionClass,
        destroyed: bool,
    ) -> Result<()> {
        if !matches!(content_type, "image/jpeg" | "image/png" | "image/webp") {
            return Err(Error::from("现场凭证仅支持 JPG、PNG 或 WebP 图片"));
        }
        if sensitivity == SensitivityClass::General {
            return Err(Error::from("现场图片凭证必须按敏感文件保存"));
        }
        if retention != RetentionClass::LongTerm {
            return Err(Error::from("现场图片凭证必须长期保留"));
        }
        if destroyed {
            return Err(Error::from("现场图片凭证已销毁"));
        }
        Ok(())
    }
}

#[cfg(test)]
mod tests {
    use super::{ActualServiceLocation, ServiceEvidencePolicy, SERVICE_LOCATION_PLACEHOLDER};
    use erp_support::{RetentionClass, SensitivityClass};

    /// 合法地点去除首尾空白并稳定保留内部字符。
    #[test]
    fn actual_service_location_trims_and_keeps_value() {
        assert_eq!(
            ActualServiceLocation::parse(" 客户现场 ").unwrap().as_str(),
            "客户现场"
        );
        assert_eq!(
            ActualServiceLocation::parse("\t\n 客户现场 1 号 \n")
                .unwrap()
                .as_str(),
            "客户现场 1 号"
        );
        assert_eq!(
            ActualServiceLocation::parse("客户现场").unwrap().as_str(),
            "客户现场"
        );
    }

    /// 空白与采购审核占位值（含带空白变体）必须拒绝，且错误不携带明文。
    #[test]
    fn actual_service_location_rejects_blank_and_placeholder() {
        for raw in ["", "   ", "\t\n"] {
            let error = ActualServiceLocation::parse(raw).unwrap_err();
            assert_eq!(error.to_string(), "服务地点不能为空");
        }
        for raw in [SERVICE_LOCATION_PLACEHOLDER, " 待填写 ", "\t待填写\n"] {
            let error = ActualServiceLocation::parse(raw).unwrap_err();
            assert_eq!(error.to_string(), "请填写实际服务地点");
            assert!(!error.to_string().contains(raw.trim()));
        }
    }

    /// 策略接受白名单图片与敏感/高敏感、长期保留、未销毁组合。
    #[test]
    fn policy_accepts_supported_image_metadata() {
        for content_type in ["image/jpeg", "image/png", "image/webp"] {
            for sensitivity in [SensitivityClass::Sensitive, SensitivityClass::HighlySensitive] {
                assert!(
                    ServiceEvidencePolicy::validate(
                        content_type,
                        sensitivity,
                        RetentionClass::LongTerm,
                        false,
                    )
                    .is_ok(),
                    "{content_type} {sensitivity:?} 应通过"
                );
            }
        }
    }

    /// 白名单之外的 MIME 一律拒绝（含空串与近似变体）。
    #[test]
    fn policy_rejects_non_image_mime() {
        for content_type in ["application/pdf", "image/gif", "image/jpg", "text/plain", ""] {
            let error = ServiceEvidencePolicy::validate(
                content_type,
                SensitivityClass::Sensitive,
                RetentionClass::LongTerm,
                false,
            )
            .unwrap_err();
            assert_eq!(error.to_string(), "现场凭证仅支持 JPG、PNG 或 WebP 图片");
        }
    }

    /// General 敏感级别拒绝，Sensitive/HighlySensitive 通过。
    #[test]
    fn policy_rejects_general_sensitivity() {
        let error = ServiceEvidencePolicy::validate(
            "image/jpeg",
            SensitivityClass::General,
            RetentionClass::LongTerm,
            false,
        )
        .unwrap_err();
        assert_eq!(error.to_string(), "现场图片凭证必须按敏感文件保存");
        assert!(ServiceEvidencePolicy::validate(
            "image/jpeg",
            SensitivityClass::Sensitive,
            RetentionClass::LongTerm,
            false,
        )
        .is_ok());
        assert!(ServiceEvidencePolicy::validate(
            "image/jpeg",
            SensitivityClass::HighlySensitive,
            RetentionClass::LongTerm,
            false,
        )
        .is_ok());
    }

    /// 非长期保留策略拒绝（30 天、7 天均失败关闭）。
    #[test]
    fn policy_rejects_non_long_term_retention() {
        for retention in [RetentionClass::ThirtyDays, RetentionClass::SevenDays] {
            let error =
                ServiceEvidencePolicy::validate("image/png", SensitivityClass::Sensitive, retention, false)
                    .unwrap_err();
            assert_eq!(error.to_string(), "现场图片凭证必须长期保留");
        }
    }

    /// 已销毁凭证拒绝。
    #[test]
    fn policy_rejects_destroyed() {
        let error = ServiceEvidencePolicy::validate(
            "image/webp",
            SensitivityClass::Sensitive,
            RetentionClass::LongTerm,
            true,
        )
        .unwrap_err();
        assert_eq!(error.to_string(), "现场图片凭证已销毁");
    }
}

entities/src/fulfillment/service_fulfill:
//! `service_fulfillment`：线下服务履约记录（数据模型 §6.7）。
//!
//! 合同 §4.3 签署为 `NO_APPROVAL`：实体只保留业务状态，不得新增审批绑定字段
//! 或审批状态机。
//!
//! 公共关键字段与 `electronic_delivery` 一致（含 `occurred_at` 等正式事实字段，
//! 组合 `FactBase`）；另保存服务地点、开始时间、结束时间和完成说明。
//! 服务地点是履约地址类敏感值，按 §4.5.5 建模为**加密值 + 带密钥 HMAC 查询
//! 指纹**两个字段，自定义 `Debug` 不泄漏。状态机按 §7.5：草稿 → 已确认 →
//! 已冲正。

use std::fmt;

use entity_core::BaseModel;
use entity_macros::Entity;
use serde::{Deserialize, Serialize};

use erp_core::common::fact::FactBase;
use erp_core::common::source::SourceType;
use erp_core::common::state::{ensure_transition, DocumentState};
use erp_core::common::time::Instant;
use erp_core::ids::{
    FileAssetId, PurchaseLineSalesAllocationId, PurchaseOrderId, SalesOrderLineId, ServiceFulfillmentId,
};
use erp_core::money::Quantity;
use erp_core::validation::normalize_optional_text;
use erp_core::validation::normalize_required_text;
use erp_core::{Error, Result};

use super::electronic_delivery::FulfillmentResult;
use super::fingerprint::{hmac_sha256_hex, validate_fingerprint, FINGERPRINT_HEX_LEN};

/// 履约记录号最大长度。
const FULFILLMENT_NO_MAX_LEN: usize = 64;
/// 交付对象加密快照最大长度。
const RECIPIENT_SNAPSHOT_MAX_LEN: usize = 4096;
/// 服务地点加密值最大长度。
const SERVICE_LOCATION_ENCRYPTED_MAX_LEN: usize = 4096;
/// 完成说明最大长度。
const COMPLETION_NOTE_MAX_LEN: usize = 512;
/// 记录人标识最大长度。
const ACTOR_MAX_LEN: usize = 128;

/// 线下服务履约状态（数据模型 §6.7：草稿、已确认、已冲正）。
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "SCREAMING_SNAKE_CASE")]
pub enum ServiceFulfillmentState {
    /// 草稿。
    Draft,
    /// 已确认（不可覆盖，纠错只能冲正）。
    Confirmed,
    /// 已冲正（不可逆终态）。
    Reversed,
}

impl ServiceFulfillmentState {
    /// 返回状态的中文展示名。
    ///
    /// # 返回
    /// 返回面向用户的中文标签。
    pub fn label(&self) -> &'static str {
        match self {
            Self::Draft => "草稿",
            Self::Confirmed => "已确认",
            Self::Reversed => "已冲正",
        }
    }

    /// 返回状态的稳定代码。
    ///
    /// # 返回
    /// 返回用于持久化与查询的稳定字符串。
    pub fn as_str(&self) -> &'static str {
        match self {
            Self::Draft => "DRAFT",
            Self::Confirmed => "CONFIRMED",
            Self::Reversed => "REVERSED",
        }
    }

    /// 判断是否可编辑（仅草稿）。
    ///
    /// # 返回
    /// 草稿状态返回 `true`。
    pub fn is_editable(&self) -> bool {
        matches!(self, Self::Draft)
    }

    /// 判断当前状态能否执行首次确认。
    ///
    /// # 返回
    /// 仅草稿状态返回 `true`。
    pub fn is_confirmable(self) -> bool {
        matches!(self, Self::Draft)
    }

    /// 判断当前状态能否作为客户验收履约事实。
    ///
    /// # 返回
    /// 已确认状态返回 `true`。
    pub fn is_acceptance_eligible(self) -> bool {
        matches!(self, Self::Confirmed)
    }
}

impl DocumentState for ServiceFulfillmentState {
    /// 固定邻接矩阵（§7.5 定向链，`REVERSED` 为不可逆终态）。
    fn allowed_next(self) -> &'static [Self] {
        match self {
            Self::Draft => &[Self::Confirmed],
            Self::Confirmed => &[Self::Reversed],
            Self::Reversed => &[],
        }
    }
}

/// 线下服务履约记录创建数据。
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
pub struct ServiceFulfillmentData {
    /// 履约记录号（全局唯一）。
    pub fulfillment_no: String,
    /// 销售责任明细。
    pub sales_order_line_id: SalesOrderLineId,
    /// 采购单。
    pub purchase_order_id: PurchaseOrderId,
    /// 对应采购行到销售行的明确分配。
    pub purchase_line_sales_allocation_id: PurchaseLineSalesAllocationId,
    /// 必要交付对象的加密快照（P3 加密生成；本层只定义结构）。
    pub recipient_snapshot: String,
    /// 交付对象快照带密钥 HMAC 查询指纹（64 位十六进制）。
    pub recipient_snapshot_fingerprint: String,
    /// 服务数量。
    pub quantity: Quantity,
    /// 履约结果。
    pub result: FulfillmentResult,
    /// 业务凭证。
    pub evidence_attachment_id: Option<FileAssetId>,
    /// 服务地点加密值（P3 加密生成；本层只定义结构）。
    pub service_location_encrypted: String,
    /// 服务地点带密钥 HMAC 查询指纹（64 位十六进制）。
    pub service_location_fingerprint: String,
    /// 服务开始时间。
    pub service_started_at: Option<Instant>,
    /// 服务结束时间（不得早于开始时间）。
    pub service_ended_at: Option<Instant>,
    /// 完成说明。
    pub completion_note: Option<String>,
    /// 聚合内稳定序号（正式事实，§4.3）。
    pub fact_no: String,
    /// 实际服务时间。
    pub occurred_at: Instant,
    /// ERP 记录时间。
    pub recorded_at: Instant,
    /// ERP 记录人或系统身份。
    pub recorded_by: String,
    /// 事实来源类型。
    pub source_type: SourceType,
    /// 可追溯的来源单据或消息引用。
    pub source_reference: Option<String>,
    /// 原因代码。
    pub reason_code: Option<String>,
    /// 原因说明文本。
    pub reason_text: Option<String>,
}

/// 线下服务履约记录更新数据（仅草稿可更新）。
#[derive(Debug, Clone, Default, Serialize, Deserialize, PartialEq, Eq)]
pub struct ServiceFulfillmentUpdate {
    /// 履约结果；`None` 表示不修改。
    pub result: Option<FulfillmentResult>,
    /// 完成说明；`None` 表示不修改。
    pub completion_note: Option<String>,
}

/// 确认线下服务履约前必须写全的现场事实。
///
/// 采购审核只生成占位草稿；确认时必须登记地点、时间窗、完成说明、数量和
/// 图片凭证。凭证以 `file_asset` 主键引用，本结构不持有文件字节。
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ServiceFulfillmentConfirmation {
    /// 履约结果。
    pub result: FulfillmentResult,
    /// 完成说明。
    pub completion_note: String,
    /// 现场图片凭证。
    pub evidence_attachment_id: FileAssetId,
    /// 服务地点加密/不透明值。
    pub service_location_encrypted: String,
    /// 服务地点查询指纹。
    pub service_location_fingerprint: String,
    /// 服务开始时间。
    pub service_started_at: Instant,
    /// 服务结束时间。
    pub service_ended_at: Instant,
    /// 本次完成数量。
    pub quantity: Quantity,
}

/// 构造 [`ServiceFulfillmentConfirmation`] 的输入参数。
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ServiceFulfillmentConfirmationParams {
    /// 履约结果。
    pub result: FulfillmentResult,
    /// 完成说明。
    pub completion_note: String,
    /// 现场图片凭证。
    pub evidence_attachment_id: FileAssetId,
    /// 服务地点加密/不透明值。
    pub service_location_encrypted: String,
    /// 服务地点查询指纹。
    pub service_location_fingerprint: String,
    /// 服务开始时间。
    pub service_started_at: Instant,
    /// 服务结束时间。
    pub service_ended_at: Instant,
    /// 本次完成数量。
    pub quantity: Quantity,
}

impl ServiceFulfillmentConfirmation {
    /// 规范化并校验确认现场事实。
    ///
    /// # 参数
    /// * `params` - 确认现场事实的全部输入
    ///
    /// # 返回
    /// 返回可写入草稿的确认事实。
    ///
    /// # 错误
    /// 结果为部分成功、说明/地点/指纹为空或超长、指纹格式非法、数量非正、
    /// 结束早于开始或凭证主键为空时返回错误。
    ///
    /// # 约束
    /// 无。
    pub fn new(params: ServiceFulfillmentConfirmationParams) -> Result<Self> {
        let result = ensure_binary_service_result(params.result)?;
        let completion_note = normalize_required_text(
            params.completion_note,
            "完成说明不能为空",
            COMPLETION_NOTE_MAX_LEN,
            "完成说明过长",
        )?;
        let evidence_attachment_id = require_evidence_attachment_id(params.evidence_attachment_id)?;
        let service_location_encrypted = normalize_required_text(
            params.service_location_encrypted,
            "服务地点加密值不能为空",
            SERVICE_LOCATION_ENCRYPTED_MAX_LEN,
            "服务地点加密值过长",
        )?;
        let service_location_fingerprint = normalize_required_text(
            params.service_location_fingerprint,
            "服务地点查询指纹不能为空",
            FINGERPRINT_HEX_LEN,
            "服务地点查询指纹过长",
        )?;
        validate_fingerprint(&service_location_fingerprint)?;
        ensure_positive_quantity(&params.quantity)?;
        ensure_service_window(params.service_started_at, params.service_ended_at)?;
        Ok(Self {
            result,
            completion_note,
            evidence_attachment_id,
            service_location_encrypted,
            service_location_fingerprint,
            service_started_at: params.service_started_at,
            service_ended_at: params.service_ended_at,
            quantity: params.quantity,
        })
    }
}

/// 线下服务履约记录实体（数据模型 §6.7）。
///
/// 组合 `FactBase` 表达正式事实语义（§4.3）；已确认记录不可覆盖，失败后重做
/// 形成新记录；冲正由反向事实表达（§6.7）。`Debug` 输出不泄漏交付对象快照、
/// 服务地点及其指纹。
#[derive(Serialize, Deserialize, Clone, Entity)]
pub struct ServiceFulfillment {
    #[serde(flatten)]
    pub base: BaseModel,
    #[serde(flatten)]
    pub fact: FactBase,
    /// 履约记录号。
    pub fulfillment_no: String,
    /// 销售责任明细。
    pub sales_order_line_id: SalesOrderLineId,
    /// 采购单。
    pub purchase_order_id: PurchaseOrderId,
    /// 对应采购行到销售行的明确分配。
    pub purchase_line_sales_allocation_id: PurchaseLineSalesAllocationId,
    /// 必要交付对象的加密快照。
    pub recipient_snapshot: String,
    /// 交付对象快照带密钥 HMAC 查询指纹。
    pub recipient_snapshot_fingerprint: String,
    /// 服务数量。
    pub quantity: Quantity,
    /// 履约结果。
    pub result: FulfillmentResult,
    /// 业务凭证。
    pub evidence_attachment_id: Option<FileAssetId>,
    /// 服务地点加密值。
    pub service_location_encrypted: String,
    /// 服务地点带密钥 HMAC 查询指纹。
    pub service_location_fingerprint: String,
    /// 服务开始时间。
    pub service_started_at: Option<Instant>,
    /// 服务结束时间。
    pub service_ended_at: Option<Instant>,
    /// 完成说明。
    pub completion_note: Option<String>,
    /// 当前状态。
    pub status: ServiceFulfillmentState,
}

impl fmt::Debug for ServiceFulfillment {
    /// 脱敏调试输出：交付对象快照、服务地点及指纹一律以 `<redacted>` 呈现。
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        formatter
            .debug_struct("ServiceFulfillment")
            .field("base", &self.base)
            .field("fact_no", &self.fact.fact_no)
            .field("occurred_at", &self.fact.occurred_at)
            .field("recorded_at", &self.fact.recorded_at)
            .field("recorded_by", &self.fact.recorded_by)
            .field("source_type", &self.fact.source_type)
            .field("source_reference", &self.fact.source_reference)
            .field("reason_code", &self.fact.reason_code)
            .field("reason_text", &self.fact.reason_text)
            .field("fulfillment_no", &self.fulfillment_no)
            .field("sales_order_line_id", &self.sales_order_line_id)
            .field("purchase_order_id", &self.purchase_order_id)
            .field(
                "purchase_line_sales_allocation_id",
                &self.purchase_line_sales_allocation_id,
            )
            .field("recipient_snapshot", &"<redacted>")
            .field("recipient_snapshot_fingerprint", &"<redacted>")
            .field("quantity", &self.quantity)
            .field("result", &self.result)
            .field("evidence_attachment_id", &self.evidence_attachment_id)
            .field("service_location_encrypted", &"<redacted>")
            .field("service_location_fingerprint", &"<redacted>")
            .field("service_started_at", &self.service_started_at)
            .field("service_ended_at", &self.service_ended_at)
            .field("completion_note", &self.completion_note)
            .field("status", &self.status)
            .finish()
    }
}

impl PartialEq for ServiceFulfillment {
    /// 全字段语义相等（`Debug` 脱敏不影响比较）。
    fn eq(&self, other: &Self) -> bool {
        self.base == other.base
            && self.fact.fact_no == other.fact.fact_no
            && self.fact.occurred_at == other.fact.occurred_at
            && self.fact.recorded_at == other.fact.recorded_at
            && self.fact.recorded_by == other.fact.recorded_by
            && self.fact.source_type == other.fact.source_type
            && self.fact.source_reference == other.fact.source_reference
            && self.fact.reason_code == other.fact.reason_code
            && self.fact.reason_text == other.fact.reason_text
            && self.fulfillment_no == other.fulfillment_no
            && self.sales_order_line_id == other.sales_order_line_id
            && self.purchase_order_id == other.purchase_order_id
            && self.purchase_line_sales_allocation_id == other.purchase_line_sales_allocation_id
            && self.recipient_snapshot == other.recipient_snapshot
            && self.recipient_snapshot_fingerprint == other.recipient_snapshot_fingerprint
            && self.quantity == other.quantity
            && self.result == other.result
            && self.evidence_attachment_id == other.evidence_attachment_id
            && self.service_location_encrypted == other.service_location_encrypted
            && self.service_location_fingerprint == other.service_location_fingerprint
            && self.service_started_at == other.service_started_at
            && self.service_ended_at == other.service_ended_at
            && self.completion_note == other.completion_note
            && self.status == other.status
    }
}

impl Eq for ServiceFulfillment {}

impl ServiceFulfillment {
    /// 生成交付对象快照查询指纹。
    ///
    /// 对必要交付对象规范化原文字符串计算带密钥 HMAC-SHA256（§4.5.5，
    /// 禁止裸摘要）；密钥不持久化，精确查询时用同一密钥比对指纹。
    ///
    /// # 参数
    /// * `plain` - 交付对象原文字符串
    /// * `key` - 查询指纹密钥字节
    ///
    /// # 返回
    /// 返回 64 位小写十六进制指纹。
    pub fn recipient_snapshot_fingerprint(plain: &str, key: &[u8]) -> String {
        hmac_sha256_hex(key, plain.as_bytes())
    }

    /// 生成服务地点查询指纹。
    ///
    /// 对规范化后的服务地点原文字符串计算带密钥 HMAC-SHA256（§4.5.5，
    /// 禁止裸摘要）；密钥不持久化，精确查询时用同一密钥比对指纹。
    ///
    /// # 参数
    /// * `plain` - 服务地点原文字符串
    /// * `key` - 查询指纹密钥字节
    ///
    /// # 返回
    /// 返回 64 位小写十六进制指纹。
    pub fn service_location_fingerprint(plain: &str, key: &[u8]) -> String {
        hmac_sha256_hex(key, plain.as_bytes())
    }

    /// 创建线下服务履约记录（初始状态为草稿）。
    ///
    /// 完成履约记录号、记录人、完成说明与快照指纹格式校验；校验
    /// `recorded_at` 不早于 `occurred_at`、服务结束时间不早于开始时间。
    /// Service 加载采购单、当前版本和采购销售分配后，由履约资格值对象校验
    /// 关联；本实体负责确认与验收事实状态。
    ///
    /// # 参数
    /// * `id` - 实体主键（`erp_core::ids::ServiceFulfillmentId`）
    /// * `data` - 创建数据
    ///
    /// # 返回
    /// 返回新建的服务履约记录实体。
    ///
    /// # 错误
    /// 必填字段为空/超长、指纹格式非法、服务数量非正、记录时间早于发生时间
    /// 或服务结束时间早于开始时间时返回错误。
    pub fn new(id: ServiceFulfillmentId, data: ServiceFulfillmentData) -> Result<Self> {
        let fulfillment_no = normalize_required_text(
            data.fulfillment_no,
            "履约记录号不能为空",
            FULFILLMENT_NO_MAX_LEN,
            "履约记录号过长",
        )?;
        let recipient_snapshot = normalize_required_text(
            data.recipient_snapshot,
            "交付对象加密快照不能为空",
            RECIPIENT_SNAPSHOT_MAX_LEN,
            "交付对象加密快照过长",
        )?;
        let recipient_snapshot_fingerprint = normalize_required_text(
            data.recipient_snapshot_fingerprint,
            "交付对象查询指纹不能为空",
            FINGERPRINT_HEX_LEN,
            "交付对象查询指纹过长",
        )?;
        validate_fingerprint(&recipient_snapshot_fingerprint)?;
        let service_location_encrypted = normalize_required_text(
            data.service_location_encrypted,
            "服务地点加密值不能为空",
            SERVICE_LOCATION_ENCRYPTED_MAX_LEN,
            "服务地点加密值过长",
        )?;
        let service_location_fingerprint = normalize_required_text(
            data.service_location_fingerprint,
            "服务地点查询指纹不能为空",
            FINGERPRINT_HEX_LEN,
            "服务地点查询指纹过长",
        )?;
        validate_fingerprint(&service_location_fingerprint)?;
        let recorded_by =
            normalize_required_text(data.recorded_by, "记录人不能为空", ACTOR_MAX_LEN, "记录人过长")?;
        let completion_note =
            normalize_optional_text(data.completion_note, "完成说明", COMPLETION_NOTE_MAX_LEN)?;
        if data.recorded_at < data.occurred_at {
            return Err(Error::from("记录时间不得早于实际服务时间"));
        }
        ensure_positive_quantity(&data.quantity)?;
        if let (Some(started_at), Some(ended_at)) = (data.service_started_at, data.service_ended_at) {
            ensure_service_window(started_at, ended_at)?;
        }

        Ok(Self {
            base: BaseModel::new(id.to_string()),
            fact: FactBase::new(
                data.fact_no,
                data.occurred_at,
                data.recorded_at,
                recorded_by,
                erp_core::common::fact::FactSource {
                    source_type: data.source_type,
                    source_reference: data.source_reference,
                    reason_code: data.reason_code,
                    reason_text: data.reason_text,
                },
            ),
            fulfillment_no,
            sales_order_line_id: data.sales_order_line_id,
            purchase_order_id: data.purchase_order_id,
            purchase_line_sales_allocation_id: data.purchase_line_sales_allocation_id,
            recipient_snapshot,
            recipient_snapshot_fingerprint,
            quantity: data.quantity,
            result: data.result,
            evidence_attachment_id: data.evidence_attachment_id,
            service_location_encrypted,
            service_location_fingerprint,
            service_started_at: data.service_started_at,
            service_ended_at: data.service_ended_at,
            completion_note,
            status: ServiceFulfillmentState::Draft,
        })
    }

    /// 返回单据注册与无审批绑定重验使用的组织上下文。
    ///
    /// # 返回
    /// 返回所属销售稳定明细主键。
    ///
    /// # 错误
    /// 销售稳定明细主键为空时返回错误。
    pub fn registration_context_id(&self) -> Result<&str> {
        let id = self.sales_order_line_id.as_ref();
        if id.trim().is_empty() {
            return Err(Error::from("服务履约缺少销售明细，无法构造绑定上下文"));
        }
        Ok(id)
    }

    /// 校验记录可执行首次确认。
    ///
    /// # 返回
    /// 草稿状态返回 `Ok(())`。
    ///
    /// # 错误
    /// 非草稿状态返回错误。
    pub fn ensure_confirmable(&self) -> Result<()> {
        if !self.status.is_confirmable() {
            return Err(Error::from("只有草稿状态的服务履约记录可以确认"));
        }
        Ok(())
    }

    /// 校验记录仍为调用方看到的草稿版本。
    ///
    /// # 参数
    /// * `expected_version` - 调用方提交的乐观锁版本
    ///
    /// # 返回
    /// 草稿且版本一致时返回 `Ok(())`。
    ///
    /// # 错误
    /// 状态不是草稿或版本不一致时返回错误。
    pub fn ensure_draft_version(&self, expected_version: u64) -> Result<()> {
        self.ensure_confirmable()?;
        if self.base.version != expected_version {
            return Err(Error::from("服务履约记录版本已变化，请刷新后重试"));
        }
        Ok(())
    }

    /// 校验确认前已登记图片凭证。
    ///
    /// # 返回
    /// 凭证主键非空时返回 `Ok(())`。
    ///
    /// # 错误
    /// 未上传图片凭证时返回错误。
    pub fn ensure_evidence_present(&self) -> Result<()> {
        let Some(evidence_attachment_id) = self.evidence_attachment_id.clone() else {
            return Err(Error::from("线下服务履约必须上传图片凭证"));
        };
        require_evidence_attachment_id(evidence_attachment_id)?;
        Ok(())
    }

    /// 校验服务履约可作为指定验收行的履约事实并返回成功数量。
    ///
    /// # 参数
    /// * `sales_order_line_id` - 验收行所属销售稳定明细
    ///
    /// # 返回
    /// 履约成功、已确认且销售明细一致时返回服务数量。
    ///
    /// # 错误
    /// 履约失败、状态无效或销售明细关联不一致时返回错误。
    pub fn acceptance_quantity(&self, sales_order_line_id: &SalesOrderLineId) -> Result<Quantity> {
        if !self.is_acceptance_eligible() {
            return Err(Error::from("服务履约事实未成功确认"));
        }
        if self.sales_order_line_id != *sales_order_line_id {
            return Err(Error::from("履约事实不属于本验收明细"));
        }
        Ok(self.quantity)
    }

    /// 判断服务履约事实是否可进入客户验收。
    ///
    /// # 返回
    /// 仅已确认且履约结果成功时返回 `true`；失败记录只保留尝试事实。
    pub fn is_acceptance_eligible(&self) -> bool {
        self.status.is_acceptance_eligible() && self.result == FulfillmentResult::Success
    }

    /// 更新线下服务履约记录（仅草稿）。
    ///
    /// 已确认记录不可覆盖（§6.7）；确认后的纠错只能冲正并新建记录。
    ///
    /// # 参数
    /// * `update` - 更新数据
    ///
    /// # 返回
    /// 更新成功返回 `Ok(())`。
    ///
    /// # 错误
    /// 状态不可编辑，或完成说明超长时返回错误。
    pub fn update(&mut self, update: ServiceFulfillmentUpdate) -> Result<()> {
        self.ensure_editable()?;
        if let Some(result) = update.result {
            self.result = result;
        }
        if let Some(completion_note) = update.completion_note {
            self.completion_note =
                normalize_optional_text(Some(completion_note), "完成说明", COMPLETION_NOTE_MAX_LEN)?;
        }
        Ok(())
    }

    /// 把确认现场事实写入草稿（仅草稿）。
    ///
    /// 覆盖占位地点、时间窗、完成说明和图片凭证；确认数量必须等于冻结的
    /// 采购销售分配数量，不在确认时改写计划数量。
    ///
    /// # 参数
    /// * `confirmation` - 已规范化的确认现场事实
    ///
    /// # 返回
    /// 写入成功返回 `Ok(())`。
    ///
    /// # 错误
    /// 状态不可编辑，或确认数量与冻结分配数量不一致时返回错误。
    pub fn apply_confirmation(&mut self, confirmation: ServiceFulfillmentConfirmation) -> Result<()> {
        self.ensure_editable()?;
        if confirmation.quantity != self.quantity {
            return Err(Error::from("服务完成数量必须与采购销售分配数量一致"));
        }
        self.result = confirmation.result;
        self.completion_note = Some(confirmation.completion_note);
        self.evidence_attachment_id = Some(confirmation.evidence_attachment_id);
        self.service_location_encrypted = confirmation.service_location_encrypted;
        self.service_location_fingerprint = confirmation.service_location_fingerprint;
        self.service_started_at = Some(confirmation.service_started_at);
        self.service_ended_at = Some(confirmation.service_ended_at);
        Ok(())
    }

    /// 确认服务履约（草稿 → 已确认）。
    ///
    /// 确认前必须已写入图片凭证；现场地点和时间由 [`Self::apply_confirmation`]
    /// 在同一确认命令内写入。已确认记录再次确认保持幂等。
    ///
    /// # 返回
    /// 迁移成功或已确认幂等时返回 `Ok(())`。
    ///
    /// # 错误
    /// 当前状态不允许迁移，或草稿尚未上传图片凭证时返回错误。
    pub fn confirm(&mut self) -> Result<()> {
        if self.status == ServiceFulfillmentState::Confirmed {
            return Ok(());
        }
        self.ensure_confirmable()?;
        self.ensure_evidence_present()?;
        ensure_transition(self.status, ServiceFulfillmentState::Confirmed)?;
        self.status = ServiceFulfillmentState::Confirmed;
        Ok(())
    }

    /// 冲正服务履约（已确认 → 已冲正，终态）。
    ///
    /// `REVERSED` 表示存在正式反向事实，不删除原记录（§4.5.1、§7.5）；
    /// 反向事实由 P3 形成。
    ///
    /// # 返回
    /// 迁移成功返回 `Ok(())`。
    ///
    /// # 错误
    /// 当前状态不允许迁移（草稿或已冲正）时返回错误。
    pub fn reverse(&mut self) -> Result<()> {
        ensure_transition(self.status, ServiceFulfillmentState::Reversed)?;
        self.status = ServiceFulfillmentState::Reversed;
        Ok(())
    }

    /// 判断当前状态是否可编辑。
    ///
    /// # 返回
    /// 草稿状态返回 `true`。
    pub fn is_editable(&self) -> bool {
        self.status.is_editable()
    }

    /// 校验当前状态可编辑。
    ///
    /// # 返回
    /// 可编辑返回 `Ok(())`。
    ///
    /// # 错误
    /// 已确认/已冲正的记录不可编辑时返回错误。
    fn ensure_editable(&self) -> Result<()> {
        if !self.is_editable() {
            return Err(Error::from("已确认或已冲正的服务履约记录不可覆盖"));
        }
        Ok(())
    }
}

/// 校验服务数量为正。
///
/// # 参数
/// * `quantity` - 待校验数量
///
/// # 返回
/// 数量为正时返回 `Ok(())`。
///
/// # 错误
/// 数量小于或等于零时返回错误。
fn ensure_positive_quantity(quantity: &Quantity) -> Result<()> {
    if quantity.to_decimal() <= rust_decimal::Decimal::ZERO {
        return Err(Error::from("服务数量必须为正数"));
    }
    Ok(())
}

/// 校验服务结束时间不早于开始时间。
///
/// # 参数
/// * `started_at` - 服务开始时间
/// * `ended_at` - 服务结束时间
///
/// # 返回
/// 时间窗合法时返回 `Ok(())`。
///
/// # 错误
/// 结束早于开始时返回错误。
fn ensure_service_window(started_at: Instant, ended_at: Instant) -> Result<()> {
    if ended_at < started_at {
        return Err(Error::from("服务结束时间不得早于开始时间"));
    }
    Ok(())
}

/// 校验线下服务履约结果只能是成功或失败。
///
/// # 参数
/// * `result` - 待确认的履约结果
///
/// # 返回
/// 成功或失败时原样返回。
///
/// # 错误
/// 结果为部分成功时返回错误。
fn ensure_binary_service_result(result: FulfillmentResult) -> Result<FulfillmentResult> {
    if matches!(result, FulfillmentResult::PartialSuccess) {
        return Err(Error::from("线下服务履约结果只能是成功或失败"));
    }
    Ok(result)
}

/// 校验图片凭证主键非空。
///
/// # 参数
/// * `evidence_attachment_id` - 文件资产主键
///
/// # 返回
/// 主键非空时原样返回。
///
/// # 错误
/// 主键空白时返回错误。
fn require_evidence_attachment_id(evidence_attachment_id: FileAssetId) -> Result<FileAssetId> {
    if evidence_attachment_id.as_ref().trim().is_empty() {
        return Err(Error::from("线下服务履约必须上传图片凭证"));
    }
    Ok(evidence_attachment_id)
}

