    fn page_and_size(&self) -> (u64, u64) {
        (self.page, u64::from(self.page_size))
    }
}

impl<'a> DeliveryRepository<'a> {
    /// 分页检索发货单列表（投影查询）。
    ///
    /// 只返回 [`DeliveryRow`] 所需的列表字段（敏感履约地址字段不进投影）；
    /// 排序字段走白名单映射（`created_at`/`shipped_at`）。
    ///
    /// # 参数
    /// * `filter` - 筛选与分页条件
    /// * `executor` - 数据访问执行器，由 Service 决定是否位于事务中
    ///
    /// # 返回
    /// 返回当前页投影行与满足筛选条件的总数。
    ///
    /// # 错误
    /// 当 MongoDB 查询、游标读取或计数失败时返回错误。
    #[tracing::instrument(
        name = "repository.fulfillment.search_deliveries",
        skip_all,
        fields(
            layer = "repository",
            domain = "fulfillment",
            db.system.name = "mongodb",
            db.collection.name = "deliveries",
            db.operation.name = "search"
        )
    )]
    pub async fn search_deliveries(
        &self,
        filter: &DeliveryFilter,
        executor: &mut dyn Executor,
    ) -> Result<PageResult<DeliveryRow>> {
        let options = FindOptions::builder()
            .sort(sort_doc(
                filter.sort_by.as_deref(),
                filter.sort_ascending,
                DELIVERY_SORT_FIELDS,
            ))
            .skip(filter.skip())
            .limit(filter.limit())
            .projection(delivery_projection())
            .build();
        let collection = self.collection().clone_with_type::<DeliveryRow>();
        let items = mongo_ops::find_many(&collection, filter.to_doc(), options, executor).await?;
        let total = mongo_ops::count_documents(&self.collection(), filter.to_doc(), executor).await?;
        Ok(PageResult {
            items,
            total: total as i64,
        })
    }
}

/// 发货单列表投影字段（履约地址敏感字段不进投影）。
///
/// # 返回
/// 返回投影条件文档。
fn delivery_projection() -> Document {
    doc! {
        "id": 1,
        "delivery_no": 1,
        "delivery_type": 1,
        "sales_order_id": 1,
        "purchase_order_id": 1,
        "warehouse_id": 1,
        "status": 1,
        "carrier": 1,
        "tracking_no": 1,
        "shipped_at": 1,
        "version": 1,
        "created_at": 1,
    }
}

#[cfg(test)]
mod tests {
    use super::{delivery_projection, sort_doc, DELIVERY_SORT_FIELDS};
    use mongodb::bson::doc;

    #[test]
    fn projection_includes_purchase_source_and_excludes_sensitive_fields() {
        let projection = delivery_projection();
        let keys: Vec<&str> = projection.keys().map(String::as_str).collect();
        assert_eq!(
            keys,
            vec![
                "id",
                "delivery_no",
                "delivery_type",
                "sales_order_id",
                "purchase_order_id",
                "warehouse_id",
                "status",
                "carrier",
                "tracking_no",
                "shipped_at",
                "version",
                "created_at",
            ],
            "列表投影必须精确等于 Row 字段集合"
        );
        assert_eq!(projection.get_i32("purchase_order_id").unwrap(), 1);
        assert!(
            !projection.contains_key("address_snapshot_encrypted"),
            "敏感履约地址不得进入发货列表投影"
        );
        assert!(
            !projection.contains_key("address_snapshot_fingerprint"),
            "地址指纹不得进入发货列表投影"
        );
    }

    #[test]
    fn sort_whitelist_maps_shipped_at_and_defaults_to_created_at() {
        assert_eq!(
            sort_doc(Some("shipped_at"), true, DELIVERY_SORT_FIELDS),
            doc! { "shipped_at": 1 },
            "白名单内字段按调用方方向排序"
        );
        assert_eq!(
            sort_doc(Some("未知字段"), false, DELIVERY_SORT_FIELDS),
            doc! { "created_at": -1 },
            "白名单外的字段名回落默认排序并保留调用方方向"
        );
    }
}

