            sort_doc(Some("未知字段"), false, PURCHASE_RECEIPT_SORT_FIELDS),
            doc! { "created_at": -1 },
            "白名单外的字段名回落默认排序并保留调用方方向"
        );
    }
}

//! `purchase_receipt_line` 累计合格收货聚合（FUL-R01）。
//!
//! 入库过账路径需要「历史累计 + 本次收货不超过采购数量」中的历史累计：
//! 按采购版本行汇总采购单全部已过账、未删除入库行的合格数量。本模块在
//! 数据库内完成过滤与聚合，只返回强类型「采购版本行 → 累计合格数量」映射，
//! 不再把入库单/入库行整实体反序列化进 Service（§6.1 责任边界）。
//!
//! 索引适配：已过账入库单查询走 `idx_purchase_receipts_po_status_posted`
//! （`purchase_order_id + status + posted_at`），入库行 `$in` 走
//! `uk_purchase_receipt_lines_header_line`（`purchase_receipt_id` 前缀）；
//! 两次固定查询，访问次数不随单据或行数增长。

use std::collections::HashMap;

use entity_core::NOT_DELETED_TIMESTAMP_BSON;
use futures_util::TryStreamExt;
use mongodb::bson::{doc, Document};
use mongodb::options::FindOptions;
use mongodb::Database;
use serde::Deserialize;

use entities::fulfillment::PurchaseReceiptState;
use erp_core::ids::{PurchaseOrderId, PurchaseOrderRevisionLineId};
use erp_core::money::Quantity;

use crate::repository::extensions::FulfillmentExt;
use persistence_core::Executor;
use persistence_core::{mongo_ops, Result};

/// 已过账入库单 ID 投影行。
#[derive(Debug, Deserialize)]
struct PostedReceiptIdRow {
    /// 入库单主键。
    id: String,
}

/// 采购入库累计合格收货聚合行。
#[derive(Debug, Deserialize)]
struct QualifiedReceivedTotalRow {
    /// 采购版本行主键（聚合分组键）。
    #[serde(rename = "_id")]
    purchase_order_revision_line_id: PurchaseOrderRevisionLineId,
    /// 累计合格数量（Decimal128 求和结果）。
    total: Quantity,
}

/// 统计采购单已过账入库的累计有效收货（按采购版本行分组）。
///
/// 先在 `purchase_receipts` 上按采购单过滤未删除且已过账的入库单并只投影
/// 主键，再在 `purchase_receipt_lines` 上按入库单主键 `$in` 过滤未删除行并
/// 按 `purchase_order_revision_line_id` 聚合 `qualified_quantity`。空结果返回
/// 空映射，不发送空 `$in`。两个查询都使用调用方执行器：位于事务内时看到
/// 同一事务的未提交写入，不自行开启事务。
///
/// # 参数
/// * `db` - 目标 MongoDB 数据库
/// * `purchase_order_id` - 采购单主键
/// * `executor` - 数据访问执行器，由 Service 决定是否位于事务中
///
/// # 返回
/// 返回「采购版本行 → 累计合格数量」映射；无任何已过账未删除入库行时返回
/// 空映射。
///
/// # 错误
/// 聚合或游标读取失败时返回错误；Decimal128 求和结果无法转换为
/// `Quantity`（精度或上限越界）时返回错误而非 panic。
pub(super) async fn load_qualified_received_totals(
    db: &Database,
    purchase_order_id: &PurchaseOrderId,
    executor: &mut dyn Executor,
) -> Result<HashMap<PurchaseOrderRevisionLineId, Quantity>> {
    let receipts = mongo_ops::find_many(
        &db.collection::<PostedReceiptIdRow>(<mongodb::Database as FulfillmentExt>::PURCHASE_RECEIPTS),
        doc! {
            "purchase_order_id": purchase_order_id.to_string(),
            "status": PurchaseReceiptState::Posted.as_str(),
            "deleted_at": NOT_DELETED_TIMESTAMP_BSON,
        },
        FindOptions::builder().projection(doc! { "id": 1 }).build(),
        executor,
    )
    .await?;
    let receipt_ids: Vec<String> = receipts.into_iter().map(|row| row.id).collect();
    if receipt_ids.is_empty() {
        return Ok(HashMap::new());
    }
    let rows = match executor.session() {
        Some(session) => {
            db.collection::<QualifiedReceivedTotalRow>(super::PURCHASE_RECEIPT_LINES)
                .aggregate(qualified_received_totals_pipeline(&receipt_ids))
                .with_type::<QualifiedReceivedTotalRow>()
                .session(&mut *session)
                .await?
                .stream(session)
                .try_collect::<Vec<_>>()
                .await?
        }
        None => {
            db.collection::<QualifiedReceivedTotalRow>(super::PURCHASE_RECEIPT_LINES)
                .aggregate(qualified_received_totals_pipeline(&receipt_ids))
                .with_type::<QualifiedReceivedTotalRow>()
                .await?
                .try_collect::<Vec<_>>()
                .await?
        }
    };
    Ok(rows
        .into_iter()
        .map(|row| (row.purchase_order_revision_line_id, row.total))
        .collect())
}

/// 构造入库行累计合格收货聚合管道。
///
/// # 参数
/// * `receipt_ids` - 已过账且未删除的入库单主键集合（非空）
///
/// # 返回
/// 返回两段聚合管道：`$match` 按入库单过滤未删除行，`$group` 按采购版本行
/// 对 `qualified_quantity` 求和。
fn qualified_received_totals_pipeline(receipt_ids: &[String]) -> Vec<Document> {
    vec![
        doc! {
            "$match": {
                "purchase_receipt_id": { "$in": receipt_ids },
                "deleted_at": NOT_DELETED_TIMESTAMP_BSON,
            }
        },
        doc! {
            "$group": {
                "_id": "$purchase_order_revision_line_id",
                "total": { "$sum": "$qualified_quantity" },
            }
        },
    ]
}

#[cfg(test)]
mod tests {
    use std::str::FromStr;

    use mongodb::bson::Bson;

    use super::*;

    /// 聚合管道只包含未删除行并按采购版本行求和合格数量。
    #[test]
    fn totals_pipeline_filters_undelted_lines_and_groups_by_revision_line() {
        let pipeline =
            qualified_received_totals_pipeline(&["receipt-1".to_string(), "receipt-2".to_string()]);
        let match_stage = pipeline[0].get_document("$match").expect("过滤阶段");
        let receipt_ids = match_stage
            .get_document("purchase_receipt_id")
            .expect("入库单主键条件")
            .get_array("$in")
            .expect("入库单主键 $in 条件");
        assert_eq!(
            receipt_ids,
            &[
                Bson::String("receipt-1".to_string()),
                Bson::String("receipt-2".to_string())
            ]
        );
        assert_eq!(match_stage.get_i64("deleted_at").expect("未删除条件"), 0);
        let group_stage = pipeline[1].get_document("$group").expect("分组阶段");
        assert_eq!(
            group_stage.get_str("_id").expect("分组键"),
            "$purchase_order_revision_line_id"
        );
        assert_eq!(
            group_stage
                .get_document("total")
                .expect("求和字段")
                .get_str("$sum")
                .expect("求和表达式"),
            "$qualified_quantity"
        );
    }

    /// Decimal128 聚合结果可反序列化为 `Quantity`。
    #[test]
    fn row_deserializes_decimal128_total() {
        let document = doc! { "_id": "po-line-1", "total": { "$numberDecimal": "12.500000" } };
        let row: QualifiedReceivedTotalRow =
            mongodb::bson::deserialize_from_document(document).expect("合法 Decimal128 必须成功");
        assert_eq!(
            row.purchase_order_revision_line_id,
            PurchaseOrderRevisionLineId::new("po-line-1")
        );
        assert_eq!(row.total, Quantity::from_str("12.5").expect("合法数量"));
    }

    /// 超精度 Decimal128 必须返回反序列化错误而非 panic。
    #[test]
    fn row_rejects_precision_overflow_without_panicking() {
        let document = doc! { "_id": "po-line-2", "total": { "$numberDecimal": "1.1234567" } };
        let result: std::result::Result<QualifiedReceivedTotalRow, mongodb::bson::error::Error> =
            mongodb::bson::deserialize_from_document(document);
        assert!(result.is_err(), "超精度 Decimal128 必须失败而非 panic");
    }
}

database/src/repository/fulfillment/serv:
//! `service_fulfillment` 线下服务履约记录仓储：列表投影查询。

use crate::repository::owned::ServiceFulfillmentRepository;
use entities::fulfillment::{FulfillmentResult, ServiceFulfillmentState};
use entity_core::NOT_DELETED_TIMESTAMP_BSON;
use erp_core::common::time::Instant;
use erp_core::ids::{PurchaseLineSalesAllocationId, PurchaseOrderId, SalesOrderLineId};
use mongodb::bson::{doc, Document};
use mongodb::options::FindOptions;
use serde::{Deserialize, Serialize};

use super::sort_doc;
use persistence_core::Executor;
use persistence_core::{mongo_ops, Result};
use persistence_core::{PageResult, Pagination, QueryFilter};

/// 线下服务履约记录排序白名单（查询与测试共用）。
const SERVICE_FULFILLMENT_SORT_FIELDS: &[&str] = &["occurred_at", "recorded_at", "created_at"];

/// 线下服务履约记录列表投影行。
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
pub struct ServiceFulfillmentRow {
    /// 实体主键。
    pub id: String,
    /// 履约记录号。
    pub fulfillment_no: String,
    /// 销售责任明细。
    pub sales_order_line_id: SalesOrderLineId,
    /// 采购单。
    pub purchase_order_id: PurchaseOrderId,
    /// 采购行到销售行的明确分配。
    pub purchase_line_sales_allocation_id: PurchaseLineSalesAllocationId,
    /// 服务数量。
    pub quantity: erp_core::money::Quantity,
    /// 履约结果。
    pub result: FulfillmentResult,
    /// 当前状态。
    pub status: ServiceFulfillmentState,
    /// 实际服务时间。
    pub occurred_at: Instant,
    /// ERP 记录时间。
    pub recorded_at: Instant,
    /// 乐观锁版本。
    pub version: u64,
}

/// 线下服务履约记录列表筛选条件。
#[derive(Debug, Clone)]
pub struct ServiceFulfillmentFilter {
    /// 销售责任明细；`None` 表示不筛选。
    pub sales_order_line_id: Option<SalesOrderLineId>,
    /// 记录状态；`None` 表示不筛选。
    pub status: Option<ServiceFulfillmentState>,
    /// 页码（1 起）。
    pub page: u64,
    /// 单页条数。
    pub page_size: u32,
    /// 排序字段（白名单内；`None` 默认 `occurred_at`）。
    pub sort_by: Option<String>,
    /// 是否升序；`false` 表示降序（默认）。
    pub sort_ascending: bool,
}

impl QueryFilter for ServiceFulfillmentFilter {
    /// 转换为 MongoDB 查询条件（自动追加未删除过滤）。
    ///
    /// # 返回
    /// 返回查询条件文档。
    fn to_doc(&self) -> Document {
        let mut filter = doc! { "deleted_at": NOT_DELETED_TIMESTAMP_BSON };
        if let Some(sales_order_line_id) = &self.sales_order_line_id {
            filter.insert("sales_order_line_id", sales_order_line_id.to_string());
        }
        if let Some(status) = self.status {
            filter.insert("status", status.as_str());
        }
        filter
    }
}

impl Pagination for ServiceFulfillmentFilter {
    /// 返回页码与单页条数。
    ///
    /// # 返回
    /// 返回 `(page, page_size)` 元组。
    fn page_and_size(&self) -> (u64, u64) {
        (self.page, u64::from(self.page_size))
    }
}

impl<'a> ServiceFulfillmentRepository<'a> {
    /// 分页检索线下服务履约记录列表（投影查询）。
    ///
    /// 只返回 [`ServiceFulfillmentRow`] 所需的列表字段（交付对象快照、服务
    /// 地点及其指纹不进投影）；排序字段走白名单映射
    /// （`occurred_at`/`recorded_at`/`created_at`）。
    ///
    /// # 参数
    /// * `filter` - 筛选与分页条件
    /// * `executor` - 数据访问执行器，由 Service 决定是否位于事务中
    ///
    /// # 返回
    /// 返回当前页投影行与满足筛选条件的总数。
    ///
    /// # 错误
    /// 当 MongoDB 查询、游标读取或计数失败时返回错误。
    #[tracing::instrument(
        name = "repository.fulfillment.search_service_fulfillments",
        skip_all,
        fields(
            layer = "repository",
            domain = "fulfillment",
            db.system.name = "mongodb",
            db.collection.name = "service_fulfillments",
            db.operation.name = "search"
        )
    )]
    pub async fn search_service_fulfillments(
        &self,
        filter: &ServiceFulfillmentFilter,
        executor: &mut dyn Executor,
    ) -> Result<PageResult<ServiceFulfillmentRow>> {
        let options = FindOptions::builder()
            .sort(sort_doc(
                filter.sort_by.as_deref(),
                filter.sort_ascending,
                SERVICE_FULFILLMENT_SORT_FIELDS,
            ))
            .skip(filter.skip())
            .limit(filter.limit())
            .projection(service_fulfillment_projection())
            .build();
        let collection = self.collection().clone_with_type::<ServiceFulfillmentRow>();
        let items = mongo_ops::find_many(&collection, filter.to_doc(), options, executor).await?;
        let total = mongo_ops::count_documents(&self.collection(), filter.to_doc(), executor).await?;
        Ok(PageResult {
            items,
            total: total as i64,
        })
    }
}

/// 服务履约记录列表投影字段（交付对象快照、服务地点及指纹不进投影）。
///
/// # 返回
/// 返回投影条件文档。
fn service_fulfillment_projection() -> Document {
    doc! {
        "id": 1,
        "fulfillment_no": 1,
        "sales_order_line_id": 1,
        "purchase_order_id": 1,
        "purchase_line_sales_allocation_id": 1,
        "quantity": 1,
        "result": 1,
        "status": 1,
        "occurred_at": 1,
        "recorded_at": 1,
        "version": 1,
    }
}

#[cfg(test)]
mod tests {
    use super::{service_fulfillment_projection, sort_doc, SERVICE_FULFILLMENT_SORT_FIELDS};
    use mongodb::bson::doc;

    #[test]
    fn projection_includes_allocation_and_excludes_snapshot_location_fields() {
        let projection = service_fulfillment_projection();
        let keys: Vec<&str> = projection.keys().map(String::as_str).collect();
        assert_eq!(
            keys,
            vec![
                "id",
                "fulfillment_no",
                "sales_order_line_id",
                "purchase_order_id",
                "purchase_line_sales_allocation_id",
                "quantity",
                "result",
                "status",
                "occurred_at",
                "recorded_at",
                "version",
            ],
            "列表投影必须精确等于 Row 字段集合"
        );
        assert!(
            !projection.contains_key("recipient_snapshot"),
            "交付对象快照不得进入服务履约列表投影"
        );
        assert!(
            !projection.contains_key("recipient_snapshot_fingerprint"),
            "快照指纹不得进入服务履约列表投影"
        );
        assert!(
            !projection.contains_key("service_location_encrypted"),
            "服务地点不得进入服务履约列表投影"
        );
        assert!(
            !projection.contains_key("service_location_fingerprint"),
            "服务地点指纹不得进入服务履约列表投影"
        );
        assert_eq!(
            projection.get_i32("purchase_line_sales_allocation_id").unwrap(),
            1
        );
    }

    #[test]
    fn sort_whitelist_maps_occurred_at_and_defaults_to_created_at() {
        assert_eq!(
            sort_doc(Some("occurred_at"), true, SERVICE_FULFILLMENT_SORT_FIELDS),
            doc! { "occurred_at": 1 },
            "白名单内字段按调用方方向排序"
        );
        assert_eq!(
            sort_doc(Some("未知字段"), false, SERVICE_FULFILLMENT_SORT_FIELDS),
            doc! { "created_at": -1 },
            "白名单外的字段名回落默认排序并保留调用方方向"
        );
    }
}

//! 域 D16 `fulfillment` 仓储：purchase_receipt(+_line)、delivery(+_line)、
//! electronic_delivery、service_fulfillment、customer_acceptance(+_line)、
//! acceptance_fulfillment_allocation（页面：W06、W09）。
//!
//! 单一集合 CRUD 与乐观锁直接复用 [`Repository`] 基类（base.rs：
//! `update`/`soft_delete`/`restore` 比较 `id + version` 做 CAS，版本不匹配返回
//! [`persistence_core::Error::OptimisticLockingError`]）；本目录按集合拆分投影行、筛选与
//! 域特有查询，根模块承载跨集合批量查询与多步骤写入入口。集合名常量统一从
//! `FulfillmentExt` 关联常量导入。
//!
//! - [`purchase_receipt`]：采购入库单列表投影与按入库单号查询；
//! - [`purchase_receipt_totals`]：采购单已过账入库行的累计合格收货聚合
//!   （FUL-R01）；
//! - [`delivery`]：发货单列表投影与按物流单号查询；
//! - [`electronic_delivery`]：电子交付记录列表投影查询；
//! - [`service_fulfillment`]：线下服务履约记录列表投影查询；
//! - [`customer_acceptance`]：客户验收单列表投影与按验收单号查询；
//! - [`FulfillmentRepository`] 承载跨集合批量取行（`$in` 一次取回，禁止 N+1）
//!   与依赖事务的表头加行写入。
//!
//! 软删除边界（§4.5）：草稿单据（采购入库单等）可逻辑删除；已过账/已发货/
//! 已确认/已冲正及分配（`electronic_delivery`、`service_fulfillment`、
//! `acceptance_fulfillment_allocation`）是正式事实，**不提供软删除方法**
//! （基类通用方法不属于本域契约）。
//!
//! 五个集合的筛选类型定义在各子模块，经本模块根 re-export 后由 `FulfillmentExt`
//! 的关联类型对外暴露（`extensions/mod.rs` 已冻结，无法在 `repository/mod.rs`
//! 增加 re-export）；投影行只作为公开搜索方法的返回类型使用，不在此处 re-export。

